fn agency_earth_native_runtime_script() -> &'static str {
    r#"
(() => {
  const STYLE_ID = "forge-agency-earth-clean";
  const DISMISS_LABELS = ["fermer", "close", "ok", "got it", "plus tard"];
  const THREE_D_LABELS = ["3d", "activer la 3d", "enable 3d"];
  const CHROME_HINTS = [
    "toolbar", "search", "drawer", "panel", "widget", "controls", "button",
    "card", "sheet", "bottom", "overlay", "floating", "popover", "place",
    "poi", "minimap", "pegman", "dialog", "modal", "header", "footer", "nav"
  ];
  const requestedSearch = (() => {
    try {
      const marker = "/web/search/";
      const href = String(location.href || "");
      const index = href.indexOf(marker);
      if (index < 0) return "";
      const raw = href.slice(index + marker.length).split(/[?#]/)[0] || "";
      return decodeURIComponent(raw.replace(/\+/g, " ")).trim();
    } catch (_) {
      return "";
    }
  })();

  const normalize = (value) => String(value || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim();

  const applyBase = () => {
    try {
      document.documentElement.style.setProperty("background", "transparent", "important");
      document.documentElement.style.setProperty("background-color", "transparent", "important");
      document.documentElement.style.setProperty("margin", "0", "important");
      document.documentElement.style.setProperty("overflow", "hidden", "important");
      if (document.body) {
        document.body.style.setProperty("background", "transparent", "important");
        document.body.style.setProperty("background-color", "transparent", "important");
        document.body.style.setProperty("margin", "0", "important");
        document.body.style.setProperty("overflow", "hidden", "important");
      }
    } catch (_) {}
  };

  const ensureStyle = () => {
    let style = document.getElementById(STYLE_ID);
    if (!style) {
      style = document.createElement("style");
      style.id = STYLE_ID;
        style.textContent = `
        html, body {
          background: transparent !important;
          background-color: transparent !important;
          overflow: hidden !important;
        }
        html[data-forge-earth-scene="0"], html[data-forge-earth-scene="0"] body,
        html[data-forge-earth-scene="1"], html[data-forge-earth-scene="1"] body {
          opacity: 1 !important;
          transition: opacity 220ms ease-out !important;
        }
        ::-webkit-scrollbar {
          display: none !important;
        }
        [data-forge-earth-hidden="1"] {
          position: fixed !important;
          left: -300vw !important;
          top: -300vh !important;
          transform: translate3d(0,0,0) !important;
          width: 1px !important;
          height: 1px !important;
          opacity: 0 !important;
          visibility: hidden !important;
          pointer-events: none !important;
          z-index: -2147483647 !important;
          overflow: hidden !important;
        }
        [data-forge-earth-prune="1"] {
          position: fixed !important;
          left: -320vw !important;
          top: -320vh !important;
          opacity: 0 !important;
          visibility: hidden !important;
          pointer-events: none !important;
          z-index: -2147483647 !important;
        }
        [data-forge-earth-bg-clear="1"] {
          background: transparent !important;
          background-color: transparent !important;
          box-shadow: none !important;
          border-color: transparent !important;
          outline-color: transparent !important;
        }
      `;
      document.documentElement.appendChild(style);
    }
  };

  const allRoots = () => {
    const roots = [document];
    for (let i = 0; i < roots.length; i += 1) {
      const root = roots[i];
      const nodes = root.querySelectorAll ? root.querySelectorAll("*") : [];
      for (const node of nodes) {
        if (node.shadowRoot) roots.push(node.shadowRoot);
      }
    }
    return roots;
  };

  const queryEverywhere = (selector) => {
    const nodes = [];
    for (const root of allRoots()) {
      try {
        nodes.push(...root.querySelectorAll(selector));
      } catch (_) {}
    }
    return nodes;
  };

  const interactiveNodes = () => queryEverywhere(
    'button, [role="button"], input, textarea, header, footer, nav, aside, dialog, [aria-modal="true"], [aria-haspopup="dialog"], [aria-label], [data-tooltip], [class*="toolbar"], [class*="Toolbar"], [class*="search"], [class*="Search"], [class*="drawer"], [class*="Drawer"], [class*="panel"], [class*="Panel"], [class*="widget"], [class*="Widget"], [class*="controls"], [class*="Controls"]'
  );

  const isVisible = (node) => {
    if (!(node instanceof Element)) return false;
    const rect = node.getBoundingClientRect();
    return rect.width > 0 && rect.height > 0;
  };

  const labelFor = (node) => normalize(
    node?.getAttribute?.("aria-label")
      || node?.getAttribute?.("title")
      || node?.getAttribute?.("data-tooltip")
      || node?.textContent
      || ""
  );

  const classSignature = (node) => normalize(
    node?.className?.baseVal
      || node?.className
      || ""
  );

  const preserveMapNode = (node) => {
    if (!(node instanceof Element)) return false;
    if (node.tagName === "CANVAS" || node.tagName === "VIDEO") return true;
    return !!node.querySelector?.("canvas, video");
  };

  const shouldHideNode = (node) => {
    if (!(node instanceof HTMLElement)) return false;
    if (!isVisible(node)) return false;
    if (preserveMapNode(node)) return false;
    const label = labelFor(node);
    const signature = `${node.tagName.toLowerCase()} ${classSignature(node)} ${label}`;
    if (CHROME_HINTS.some((hint) => signature.includes(hint))) return true;
    const style = window.getComputedStyle(node);
    const positioned = style.position === "fixed" || style.position === "sticky" || style.position === "absolute";
    const decorative = node.childElementCount > 0 || label.length > 0 || ["INPUT", "BUTTON", "IMG", "SVG"].includes(node.tagName);
    return positioned && decorative;
  };

  const clickMatching = (labels) => {
    for (const node of interactiveNodes()) {
      if (!isVisible(node)) continue;
      const label = labelFor(node);
      if (!label) continue;
      if (labels.some((entry) => label === entry || label.includes(entry))) {
        try {
          node.click();
          return true;
        } catch (_) {}
      }
    }
    return false;
  };

  const hideChrome = () => {
    const candidates = queryEverywhere(
      'button, [role="button"], input, header, footer, nav, aside, dialog, [aria-modal="true"], [aria-haspopup="dialog"], [aria-label], [data-tooltip], [class], [id], img, picture, svg'
    );
    for (const node of candidates) {
      if (!(node instanceof HTMLElement)) continue;
      if (shouldHideNode(node)) {
        node.dataset.forgeEarthHidden = "1";
      }
    }
    const wrappers = queryEverywhere("div, section, article, main, earth-app, earth-ui, earth-search, earth-drawer");
    for (const node of wrappers) {
      if (!(node instanceof HTMLElement)) continue;
      if (!isVisible(node) || preserveMapNode(node)) continue;
      node.dataset.forgeEarthBgClear = "1";
      const signature = `${classSignature(node)} ${labelFor(node)}`;
      if (CHROME_HINTS.some((hint) => signature.includes(hint))) {
        node.dataset.forgeEarthPrune = "1";
      }
    }
  };

  const dispatchText = (node, value) => {
    try {
      const proto = node instanceof HTMLTextAreaElement ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
      const setter = Object.getOwnPropertyDescriptor(proto, "value")?.set;
      if (setter) setter.call(node, value);
      else node.value = value;
      node.dispatchEvent(new Event("input", { bubbles: true, composed: true }));
      node.dispatchEvent(new Event("change", { bubbles: true, composed: true }));
      return true;
    } catch (_) {
      return false;
    }
  };

  const injectSearch = () => {
    if (!requestedSearch) return false;
    if (window.__forgeEarthSearchInjected === requestedSearch) return true;
    const candidates = queryEverywhere('input[type="search"], input[aria-label*="Search"], input[aria-label*="search"], input[placeholder*="Search"], input[placeholder*="search"], input, textarea')
      .filter((node) => node instanceof HTMLInputElement || node instanceof HTMLTextAreaElement);
    for (const input of candidates) {
      if (!isVisible(input)) continue;
      const label = labelFor(input);
      const placeholder = normalize(input.getAttribute("placeholder") || "");
      const likely = input.type === "search" || label.includes("search") || label.includes("rechercher") || placeholder.includes("search") || placeholder.includes("rechercher");
      if (!likely) continue;
      try {
        input.focus();
        if (!dispatchText(input, requestedSearch)) continue;
        input.dispatchEvent(new KeyboardEvent("keydown", { key: "Enter", code: "Enter", bubbles: true, composed: true }));
        input.dispatchEvent(new KeyboardEvent("keyup", { key: "Enter", code: "Enter", bubbles: true, composed: true }));
        window.__forgeEarthSearchInjected = requestedSearch;
        return true;
      } catch (_) {}
    }
    return false;
  };

  const maybeEnable3d = () => {
    const now = Date.now();
    if ((window.__forgeEarth3DClickedAt || 0) + 2500 > now) return;
    if (clickMatching(THREE_D_LABELS)) {
      window.__forgeEarth3DClickedAt = now;
    }
  };

  const updateSceneVisibility = () => {
    document.documentElement.dataset.forgeEarthScene = "1";
  };

  const tick = () => {
    applyBase();
    ensureStyle();
    clickMatching(DISMISS_LABELS);
    injectSearch();
    maybeEnable3d();
    hideChrome();
    updateSceneVisibility();
  };

  const observer = new MutationObserver(() => {
    window.requestAnimationFrame(tick);
  });

  applyBase();
  ensureStyle();
  tick();
  observer.observe(document.documentElement, {
    childList: true,
    subtree: true,
    attributes: true,
    characterData: false,
  });
  window.addEventListener("DOMContentLoaded", tick, { once: true });
  window.addEventListener("load", () => {
    tick();
    window.setTimeout(tick, 600);
    window.setTimeout(tick, 1800);
  }, { once: true });
  window.setInterval(tick, 2500);
})();
"#
}

fn normalize_real_estate_tool_command(command: &str) -> Result<String, String> {
    let token = command
        .trim()
        .split_whitespace()
        .next()
        .unwrap_or_default();
    if !token.starts_with('/') || !token.ends_with('_') {
        return Err("real estate tool commands must use /(nom_outil)_".to_string());
    }
    let body = &token[1..token.len().saturating_sub(1)];
    if body.is_empty()
        || body.len() > 64
        || !body
            .chars()
            .all(|ch| ch.is_ascii_lowercase() || ch.is_ascii_digit() || ch == '_')
    {
        return Err("invalid real estate tool command name".to_string());
    }
    Ok(format!("/{body}_"))
}

fn real_estate_json_path_string(value: &JsonValue, path: &[&str]) -> Option<String> {
    let mut node = value;
    for key in path {
        node = node.get(*key)?;
    }
    node.as_str().map(|text| text.trim().to_string()).filter(|text| !text.is_empty())
}

fn real_estate_json_path_array_contains(value: &JsonValue, path: &[&str], needle: &str) -> bool {
    let mut node = value;
    for key in path {
        let Some(next) = node.get(*key) else {
            return false;
        };
        node = next;
    }
    node.as_array()
        .map(|items| items.iter().any(|item| item.as_str() == Some(needle)))
        .unwrap_or(false)
}

fn real_estate_truncate_chars(text: &str, max_chars: usize) -> String {
    if text.chars().count() <= max_chars {
        return text.to_string();
    }
    let mut out = text.chars().take(max_chars.saturating_sub(3)).collect::<String>();
    out.push_str("...");
    out
}

fn real_estate_memory_commit_score(commit: &JsonValue, command: &str, program_name: &str) -> i32 {
    let tool_id = program_name.replace('_', "-");
    let mut score = 0;
    if real_estate_json_path_array_contains(commit, &["toolRouting", "primaryCommands"], command) {
        score += 100;
    }
    if real_estate_json_path_string(commit, &["actionId"])
        .map(|text| text.contains(program_name) || text.contains(&tool_id))
        .unwrap_or(false)
    {
        score += 24;
    }
    if real_estate_json_path_string(commit, &["scenario"])
        .map(|text| text.contains(program_name) || text.contains(&tool_id))
        .unwrap_or(false)
    {
        score += 20;
    }
    if real_estate_json_path_string(commit, &["noteText"])
        .map(|text| text.contains(command) || text.contains(program_name) || text.contains(&tool_id))
        .unwrap_or(false)
    {
        score += 16;
    }
    if real_estate_json_path_string(commit, &["brainCommitRequest", "text"])
        .map(|text| text.contains(command) || text.contains(program_name) || text.contains(&tool_id))
        .unwrap_or(false)
    {
        score += 16;
    }
    if real_estate_json_path_string(commit, &["decision"])
        .map(|text| text == "run_now" || text == "ready")
        .unwrap_or(false)
    {
        score += 4;
    }
    score
}

fn read_real_estate_memory_commits(
    store_path: &Path,
    command: &str,
    program_name: &str,
    limit: usize,
) -> JsonValue {
    let path = store_path
        .join("real-estate-harvester")
        .join("data")
        .join("real_estate_memory_commits.jsonl");
    let Ok(raw) = std::fs::read_to_string(&path) else {
        return json!({
            "status": "missing",
            "path": path.to_string_lossy(),
            "selected": [],
            "selection": {
                "read": 0,
                "selected": 0,
                "matched": 0
            }
        });
    };
    let mut scored: Vec<(i32, usize, JsonValue)> = raw
        .lines()
        .enumerate()
        .filter_map(|(idx, line)| {
            let trimmed = line.trim();
            if trimmed.is_empty() {
                return None;
            }
            serde_json::from_str::<JsonValue>(trimmed)
                .ok()
                .map(|commit| (real_estate_memory_commit_score(&commit, command, program_name), idx, commit))
        })
        .collect();
    scored.sort_by(|a, b| b.0.cmp(&a.0).then_with(|| b.1.cmp(&a.1)));
    let read_count = scored.len();
    let matched_count = scored.iter().filter(|(score, _, _)| *score > 0).count();
    let selected = scored
        .into_iter()
        .take(limit.max(1).min(8))
        .map(|(score, _, commit)| {
            json!({
                "score": score,
                "actionId": real_estate_json_path_string(&commit, &["actionId"]),
                "scenario": real_estate_json_path_string(&commit, &["scenario"]),
                "decision": real_estate_json_path_string(&commit, &["decision"]),
                "confidence": commit.get("confidence").cloned(),
                "noteText": real_estate_json_path_string(&commit, &["noteText"])
                    .map(|text| real_estate_truncate_chars(&text, 1400)),
                "brainCommitRequest": commit.get("brainCommitRequest").cloned(),
                "toolRouting": commit.get("toolRouting").cloned(),
                "evidence": commit.get("evidence").cloned()
            })
        })
        .collect::<Vec<_>>();
    let selected_count = selected.len();
    json!({
        "status": "ready",
        "path": path.to_string_lossy(),
        "selected": selected,
        "selection": {
            "read": read_count,
            "selected": selected_count,
            "matched": matched_count
        }
    })
}

#[tauri::command]
fn real_estate_tool_command_context(
    command: String,
    state: tauri::State<'_, Mutex<ForgeAppState>>,
) -> Result<JsonValue, String> {
    let command = normalize_real_estate_tool_command(&command)?;
    let program_name = command
        .trim_start_matches('/')
        .trim_end_matches('_')
        .to_string();
    let tool_id = program_name.replace('_', "-");
    let store_path = {
        let state = state.lock().map_err(|e| e.to_string())?;
        state.store_path.clone()
    };
    let snapshot = real_estate_harvester::snapshot(&store_path).ok();
    let memory_commits = read_real_estate_memory_commits(&store_path, &command, &program_name, 4);
    let brain_state = forge_agent_runtime::direct_state_kernel_read(
        &store_path,
        &json!({
            "state": "brain",
            "op": "recall",
            "scope": "agence_immo",
            "memory_layer": "semantic",
            "limit": 8
        }),
    )?;
    let brain = brain_state.get("result").cloned().unwrap_or(JsonValue::Null);
    Ok(json!({
        "kind": "real_estate_tool_command_context",
        "command": command,
        "program_name": program_name,
        "tool_id": tool_id,
        "scope": "agence_immo",
        "memory_layer": "semantic",
        "route": {
            "slash": command,
            "program_to_run": true,
            "brain_first": "brain_recall",
            "memory_scope": "agence_immo",
            "data_sync": "real_estate_harvester_snapshot",
            "memory_commits": "real_estate_memory_commits.jsonl"
        },
        "harvester_snapshot": snapshot,
        "memory_commits": memory_commits,
        "brain": brain,
        "brain_state_kernel": brain_state
    }))
}

