    fn analysis_snapshot(&mut self) -> WebExplorerAnalysisSnapshot {
        const ANALYSIS_JOB_COUNT: u64 = 4;
        let started = Instant::now();
        if let Some(cached) = self.memory.analysis.clone() {
            if cached.snapshot.revision == self.memory.revision {
                self.memory.analysis_cache_hits = self.memory.analysis_cache_hits.saturating_add(1);
                self.memory.analysis_jobs_avoided = self
                    .memory
                    .analysis_jobs_avoided
                    .saturating_add(ANALYSIS_JOB_COUNT);
                self.memory.last_analysis_cache_hit = true;
                self.memory.last_analysis_elapsed_us = started.elapsed().as_micros() as u64;
                let mut analysis = cached;
                analysis.proof = self.build_analysis_proof(
                    &analysis.snapshot,
                    true,
                    self.memory.last_analysis_elapsed_us,
                    analysis.content_plan.blocks.len(),
                    false,
                    false,
                    String::new(),
                );
                self.memory.analysis = Some(analysis.clone());
                return analysis;
            }
        }
        let snapshot = self.memory_snapshot();
        let tree_hash = snapshot.tree_hash.clone();
        let mut persistent_cache_hit = false;
        let mut persistent_cache_saved = false;
        let mut persistent_ledger_hash = String::new();
        let (bundle, cache_hit) = if let Some(cached) = self.memory.analysis_cache.get(&tree_hash).cloned() {
            self.memory.analysis_cache_hits = self.memory.analysis_cache_hits.saturating_add(1);
            self.memory.analysis_jobs_avoided = self
                .memory
                .analysis_jobs_avoided
                .saturating_add(ANALYSIS_JOB_COUNT);
            (cached, true)
        } else if let Some((bundle, artifact_hash)) = webexplorer_load_persistent_analysis_bundle(&tree_hash) {
            persistent_cache_hit = true;
            persistent_ledger_hash = artifact_hash;
            self.memory.analysis_cache_hits = self.memory.analysis_cache_hits.saturating_add(1);
            self.memory.analysis_jobs_avoided = self
                .memory
                .analysis_jobs_avoided
                .saturating_add(ANALYSIS_JOB_COUNT);
            self.insert_analysis_cache_bundle(tree_hash, bundle.clone());
            (bundle, true)
        } else {
            self.memory.analysis_cache_misses = self.memory.analysis_cache_misses.saturating_add(1);
            self.memory.analysis_jobs_executed = self
                .memory
                .analysis_jobs_executed
                .saturating_add(ANALYSIS_JOB_COUNT);
            let bundle = webexplorer_analysis_bundle_from_snapshot(&snapshot);
            if let Some(artifact_hash) = webexplorer_store_persistent_analysis_bundle(&snapshot, &bundle) {
                persistent_cache_saved = true;
                persistent_ledger_hash = artifact_hash;
            }
            self.insert_analysis_cache_bundle(tree_hash, bundle.clone());
            (bundle, false)
        };
        self.memory.last_analysis_cache_hit = cache_hit;
        self.memory.last_analysis_elapsed_us = started.elapsed().as_micros() as u64;
        let mut analysis = WebExplorerAnalysisSnapshot {
            proof: WebExplorerPerfProof::default(),
            semantic_plan: bundle.semantic_plan,
            rewrite_plan: bundle.rewrite_plan,
            region_plan: bundle.region_plan,
            content_plan: bundle.content_plan,
            snapshot,
        };
        analysis.proof = self.build_analysis_proof(
            &analysis.snapshot,
            cache_hit,
            self.memory.last_analysis_elapsed_us,
            analysis.content_plan.blocks.len(),
            persistent_cache_hit,
            persistent_cache_saved,
            persistent_ledger_hash,
        );
        self.memory.analysis = Some(analysis.clone());
        analysis
    }

    fn build_analysis_proof(
        &self,
        snapshot: &WebExplorerMemorySnapshot,
        cache_hit: bool,
        analysis_elapsed_us: u64,
        content_blocks: usize,
        persistent_cache_hit: bool,
        persistent_cache_saved: bool,
        persistent_ledger_hash: String,
    ) -> WebExplorerPerfProof {
        let visible_nodes = snapshot.nodes.iter().filter(|node| node.visible).count();
        let dom = self.memory.dom.as_ref();
        WebExplorerPerfProof {
            sampled_at_ms: now_epoch_ms() as u64,
            tree_hash: snapshot.tree_hash.clone(),
            analysis_cache_hit: cache_hit,
            analysis_cache_entries: self.memory.analysis_cache.len(),
            analysis_cache_evictions: self.memory.analysis_cache_evictions,
            analysis_cache_estimated_bytes: self.memory.analysis_cache_estimated_bytes,
            analysis_cache_max_entries: webexplorer_analysis_cache_max_entries(),
            analysis_cache_max_bytes: webexplorer_analysis_cache_max_bytes(),
            analysis_cache_hits: self.memory.analysis_cache_hits,
            analysis_cache_misses: self.memory.analysis_cache_misses,
            atlas_cache_checked: false,
            atlas_cache_hit: false,
            atlas_cache_hits: self.memory.atlas_cache_hits,
            atlas_cache_misses: self.memory.atlas_cache_misses,
            content_address_hash: webexplorer_analysis_content_address(&snapshot.tree_hash),
            persistent_cache_hit,
            persistent_cache_saved,
            persistent_ledger_hash,
            kasm_jobs_executed: self.memory.analysis_jobs_executed,
            kasm_jobs_avoided: self.memory.analysis_jobs_avoided,
            analysis_elapsed_us,
            dom_capture_elapsed_ms: dom.map(|it| it.capture_elapsed_ms).unwrap_or(0.0),
            rust_commit_elapsed_us: self.memory.last_commit_elapsed_us,
            receive_lag_ms: self.memory.last_receive_lag_ms,
            nodes_scanned: dom
                .map(|it| it.scanned_node_count)
                .filter(|count| *count > 0)
                .unwrap_or(snapshot.node_count),
            max_nodes: dom.map(|it| it.max_nodes).unwrap_or(0),
            visible_nodes,
            content_blocks,
            classifier_cache_entries: self.classifier_cache.len(),
            classifier_kasm_executed: self.classifier_kasm_executed,
            classifier_kasm_avoided: self.classifier_kasm_avoided,
            note: "WebExplorer proof counters are measured in the native bridge; WebView2 GPU engine is probed separately because Windows owns page rendering.".to_string(),
        }
    }

    fn insert_analysis_cache_bundle(
        &mut self,
        tree_hash: String,
        bundle: WebExplorerAnalysisPlanBundle,
    ) {
        if let Some(previous) = self.memory.analysis_cache.remove(&tree_hash) {
            let previous_bytes = webexplorer_estimate_analysis_bundle_bytes(&previous);
            self.memory.analysis_cache_estimated_bytes = self
                .memory
                .analysis_cache_estimated_bytes
                .saturating_sub(previous_bytes);
            self.memory
                .analysis_cache_order
                .retain(|cached| cached != &tree_hash);
        }
        let estimated_bytes = webexplorer_estimate_analysis_bundle_bytes(&bundle);
        self.memory
            .analysis_cache
            .insert(tree_hash.clone(), bundle);
        self.memory.analysis_cache_order.push_back(tree_hash);
        self.memory.analysis_cache_estimated_bytes = self
            .memory
            .analysis_cache_estimated_bytes
            .saturating_add(estimated_bytes);
        self.trim_analysis_cache();
    }

    fn trim_analysis_cache(&mut self) {
        let max_entries = webexplorer_analysis_cache_max_entries();
        let max_bytes = webexplorer_analysis_cache_max_bytes();
        loop {
            let over_entries = self.memory.analysis_cache.len() > max_entries;
            let over_bytes = self.memory.analysis_cache_estimated_bytes > max_bytes
                && self.memory.analysis_cache.len() > 1;
            if !over_entries && !over_bytes {
                break;
            }
            let Some(evicted_key) = self.memory.analysis_cache_order.pop_front() else {
                break;
            };
            if let Some(evicted) = self.memory.analysis_cache.remove(&evicted_key) {
                let evicted_bytes = webexplorer_estimate_analysis_bundle_bytes(&evicted);
                self.memory.analysis_cache_estimated_bytes = self
                    .memory
                    .analysis_cache_estimated_bytes
                    .saturating_sub(evicted_bytes);
                self.memory.analysis_cache_evictions =
                    self.memory.analysis_cache_evictions.saturating_add(1);
            }
        }
    }

    fn apply_atlas_proof(
        &mut self,
        analysis: &mut WebExplorerAnalysisSnapshot,
        checked: bool,
        hit: bool,
    ) {
        if checked {
            if hit {
                self.memory.atlas_cache_hits = self.memory.atlas_cache_hits.saturating_add(1);
            } else {
                self.memory.atlas_cache_misses = self.memory.atlas_cache_misses.saturating_add(1);
            }
        }
        analysis.proof.atlas_cache_checked = checked;
        analysis.proof.atlas_cache_hit = checked && hit;
        analysis.proof.atlas_cache_hits = self.memory.atlas_cache_hits;
        analysis.proof.atlas_cache_misses = self.memory.atlas_cache_misses;
        if let Some(cached) = self.memory.analysis.as_mut() {
            if cached.snapshot.revision == analysis.snapshot.revision {
                cached.proof = analysis.proof.clone();
            }
        }
    }

