// les logs/results de la section ÃƒÆ’Ã†â€™Ãƒâ€¦Ã‚Â½ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¨ DNA. Le frontend Alpha listen sur
// `alpha-log` (Forge logs tab) et `alpha-signal` (markers chart).
fn emit_alpha_log(app: &tauri::AppHandle, msg: String) {
    let _ = app.emit("alpha-log", msg);
}

fn emit_alpha_signal(app: &tauri::AppHandle, msg: String) {
    let _ = app.emit("alpha-signal", msg);
}

fn emit_alpha_signal_reset(app: &tauri::AppHandle) {
    let _ = app.emit("alpha-signal-reset", "");
}

fn terminal_status_len() -> &'static Mutex<usize> {
    static LEN: OnceLock<Mutex<usize>> = OnceLock::new();
    LEN.get_or_init(|| Mutex::new(0))
}

fn clear_terminal_status_line() {
    let mut guard = match terminal_status_len().lock() {
        Ok(guard) => guard,
        Err(_) => return,
    };
    if *guard > 0 {
        eprint!("\r{}\r", " ".repeat(*guard));
        let _ = std::io::stderr().flush();
        *guard = 0;
    }
}

fn emit_terminal_status_line(message: &str) {
    let mut guard = match terminal_status_len().lock() {
        Ok(guard) => guard,
        Err(_) => return,
    };
    let line = format!("[forge-status] {}", message.trim());
    let pad = guard.saturating_sub(line.len());
    eprint!("\r{line}{}", " ".repeat(pad));
    let _ = std::io::stderr().flush();
    *guard = line.len();
}

fn alpha_trace_terminal_worthy(source: &str, message: &str) -> bool {
    if std::env::var("FORGE_TERMINAL_TRACE")
        .map(|value| matches!(value.as_str(), "1" | "true" | "TRUE" | "debug" | "trace"))
        .unwrap_or(false)
    {
        return true;
    }

    let msg = message.to_ascii_lowercase();
    msg.contains(".error")
        || msg.contains(" error")
        || msg.contains("failed")
        || msg.contains("timeout")
        || msg.contains("blocked")
        || msg.contains("panic")
        || msg.contains("unhandledrejection")
        || msg.contains("cannot ")
        || msg.contains("unavailable")
        || (!source.is_empty() && msg.contains("denied"))
}

fn alpha_trace<R: Runtime>(app: &tauri::AppHandle<R>, source: &str, message: impl AsRef<str>) {
    let message = message.as_ref();
    let ts_ms = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_millis())
        .unwrap_or(0);
    let line = format!("[alpha-trace {ts_ms}] {source}: {message}");
    if alpha_trace_terminal_worthy(source, message) {
        clear_terminal_status_line();
        eprintln!("{line}");
    }

    if let Ok(app_dir) = app.path().app_data_dir() {
        let _ = std::fs::create_dir_all(&app_dir);
        let path = app_dir.join("alpha-start-trace.log");
        if let Ok(mut file) = OpenOptions::new().create(true).append(true).open(path) {
            let _ = std::io::Write::write_all(&mut file, line.as_bytes());
            let _ = std::io::Write::write_all(&mut file, b"\n");
        }
    }

    let tmp_path = PathBuf::from(r"C:\tmp\forge-alpha-start-trace.log");
    if let Some(parent) = tmp_path.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    if let Ok(mut file) = OpenOptions::new().create(true).append(true).open(tmp_path) {
        let _ = std::io::Write::write_all(&mut file, line.as_bytes());
        let _ = std::io::Write::write_all(&mut file, b"\n");
    }
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
struct BackendReadyReport {
    open_ms: u64,
    wait_ms: u64,
    already_ready: bool,
}

fn ensure_backend_ready(
    state: &tauri::State<'_, Mutex<ForgeAppState>>,
    app: &tauri::AppHandle,
    reason: &str,
) -> Result<BackendReadyReport, String> {
    let total_t0 = Instant::now();
    let mut waited_for_existing_open = false;
    let mut wait_log_ticks = 0usize;
    loop {
        let action = {
            let mut app_state = state.lock().map_err(|e| e.to_string())?;
            if app_state.backend.is_some() {
                None
            } else if app_state.backend_opening {
                waited_for_existing_open = true;
                Some(None)
            } else {
                app_state.backend_opening = true;
                Some(Some(app_state.store_path.clone()))
            }
        };

        match action {
            None => {
                return Ok(BackendReadyReport {
                    open_ms: 0,
                    wait_ms: total_t0.elapsed().as_millis() as u64,
                    already_ready: !waited_for_existing_open,
                });
            }
            Some(None) => {
                if wait_log_ticks % 20 == 0 {
                    alpha_trace(
                        app,
                        "backend",
                        format!(
                            "{reason}.backend_open.wait_existing elapsed_ms={}",
                            total_t0.elapsed().as_millis()
                        ),
                    );
                }
                wait_log_ticks = wait_log_ticks.saturating_add(1);
                thread::sleep(Duration::from_millis(250));
            }
            Some(Some(store_path)) => {
                let open_t0 = Instant::now();
                alpha_trace(
                    app,
                    "backend",
                    format!("{reason}.backend_open.begin path={}", store_path.display()),
                );
                match ForgeBackend::new(store_path) {
                    Ok(backend) => {
                        let open_ms = open_t0.elapsed().as_millis() as u64;
                        let mut app_state = state.lock().map_err(|e| e.to_string())?;
                        app_state.backend = Some(backend);
                        app_state.backend_opening = false;
                        alpha_trace(
                            app,
                            "backend",
                            format!("{reason}.backend_open.done open_ms={open_ms}"),
                        );
                        return Ok(BackendReadyReport {
                            open_ms,
                            wait_ms: total_t0.elapsed().as_millis() as u64,
                            already_ready: false,
                        });
                    }
                    Err(err) => {
                        if let Ok(mut app_state) = state.lock() {
                            app_state.backend_opening = false;
                        }
                        return Err(format!("ForgeBackend init (Store + KASM programs): {err}"));
                    }
                }
            }
        }
    }
}

#[tauri::command]
fn alpha_debug_log(
    stage: String,
    details: Option<String>,
    app: tauri::AppHandle,
) -> Result<(), String> {
    if stage == "terminal.status" && std::env::var("FORGE_TERMINAL_STATUS").as_deref() == Ok("1") {
        emit_terminal_status_line(details.as_deref().unwrap_or(""));
        return Ok(());
    }
    match details {
        Some(details) if !details.trim().is_empty() => {
            alpha_trace(&app, "frontend", format!("{stage} {details}"));
        }
        _ => alpha_trace(&app, "frontend", stage),
    }
    Ok(())
}

#[derive(Clone, Serialize)]
