fn tune_native_webview_builder<R: Runtime>(
    builder: WebviewBuilder<R>,
    media_surface: bool,
) -> WebviewBuilder<R> {
    let mut builder = builder
        .disable_drag_drop_handler()
        .zoom_hotkeys_enabled(false)
        .browser_extensions_enabled(false)
        .devtools(false)
        .background_color(Color(0, 0, 0, 255));
    if media_surface {
        let data_directory = bloomberg_webview_data_directory();
        let _ = std::fs::create_dir_all(&data_directory);
        builder = builder
            .focused(false)
            .data_directory(data_directory);
    }
    #[cfg(target_os = "macos")]
    let builder = builder.allow_link_preview(false);
    builder
}

fn tune_native_platform_webview<R: Runtime>(
    app: &tauri::AppHandle<R>,
    label: &str,
    role: &str,
) {
    let Some(webview) = app.get_webview(label) else {
        return;
    };
    let _ = webview.set_zoom(1.0);
    let app_for_trace = app.clone();
    let label_for_trace = label.to_string();
    let role_for_trace = role.to_string();
    let _ = webview.with_webview(move |platform| {
        #[cfg(windows)]
        unsafe {
            let result = (|| -> Result<(), String> {
                let controller = platform.controller();
                let _ = controller.SetZoomFactor(1.0);
                let core = controller
                    .CoreWebView2()
                    .map_err(|err| format!("core-webview2: {err:?}"))?;
                let settings = core
                    .Settings()
                    .map_err(|err| format!("settings: {err:?}"))?;
                let _ = settings.SetAreDefaultContextMenusEnabled(false);
                let _ = settings.SetAreDevToolsEnabled(false);
                let _ = settings.SetIsStatusBarEnabled(false);
                let _ = settings.SetIsZoomControlEnabled(false);
                Ok(())
            })();
            match result {
                Ok(()) => alpha_trace(
                    &app_for_trace,
                    "native.webview.adapter",
                    format!("{label_for_trace}.windows.tuned role={role_for_trace}"),
                ),
                Err(err) => alpha_trace(
                    &app_for_trace,
                    "native.webview.adapter",
                    format!("{label_for_trace}.windows.tune.error {err}"),
                ),
            }
        }
        #[cfg(any(target_os = "macos", target_os = "ios"))]
        {
            alpha_trace(
                &app_for_trace,
                "native.webview.adapter",
                format!("{label_for_trace}.webkit.builder-tuned role={role_for_trace}"),
            );
        }
        #[cfg(not(any(windows, target_os = "macos", target_os = "ios")))]
        {
            alpha_trace(
                &app_for_trace,
                "native.webview.adapter",
                format!("{label_for_trace}.portable.builder-tuned role={role_for_trace}"),
            );
        }
    });
}

