fn webexplorer_bridge_read_request(
    stream: &mut std::net::TcpStream,
) -> Result<(String, String, Vec<u8>), String> {
    let _ = stream.set_read_timeout(Some(Duration::from_secs(3)));
    let mut buffer = Vec::with_capacity(16 * 1024);
    let mut header_end = None;
    let mut chunk = [0u8; 4096];
    while header_end.is_none() && buffer.len() < 512 * 1024 {
        let read = stream.read(&mut chunk).map_err(|e| e.to_string())?;
        if read == 0 {
            break;
        }
        buffer.extend_from_slice(&chunk[..read]);
        if let Some(pos) = buffer.windows(4).position(|window| window == b"\r\n\r\n") {
            header_end = Some(pos + 4);
        }
    }
    let header_end = header_end.ok_or_else(|| "http header not complete".to_string())?;
    let header_text = String::from_utf8_lossy(&buffer[..header_end]).into_owned();
    let mut header_lines = header_text.split("\r\n").filter(|line| !line.is_empty());
    let request_line = header_lines
        .next()
        .ok_or_else(|| "missing request line".to_string())?;
    let mut request_parts = request_line.split_whitespace();
    let method = request_parts
        .next()
        .ok_or_else(|| "missing method".to_string())?
        .to_string();
    let path = request_parts
        .next()
        .ok_or_else(|| "missing path".to_string())?
        .to_string();
    let mut content_length = 0usize;
    for line in header_lines {
        if let Some((name, value)) = line.split_once(':') {
            if name.trim().eq_ignore_ascii_case("content-length") {
                content_length = value.trim().parse::<usize>().unwrap_or(0);
            }
        }
    }
    while buffer.len() < header_end.saturating_add(content_length) && buffer.len() < 4 * 1024 * 1024 {
        let read = stream.read(&mut chunk).map_err(|e| e.to_string())?;
        if read == 0 {
            break;
        }
        buffer.extend_from_slice(&chunk[..read]);
    }
    let available = buffer.len().saturating_sub(header_end);
    let body_len = available.min(content_length);
    let body = buffer[header_end..header_end + body_len].to_vec();
    Ok((method, path, body))
}

fn webexplorer_memory_commit_dom_internal<R: Runtime>(
    app: &tauri::AppHandle<R>,
    snapshot: WebExplorerDomSnapshotInput,
) {
    let state = app.state::<Mutex<ForgeAppState>>();
    let commit_url = snapshot.current_url.clone();
    if webexplorer_is_google_account_url(&commit_url) {
        alpha_trace(
            app,
            "webexplorer.memory",
            "commit.skip.google-account",
        );
        return;
    }
    let captured_at_ms = snapshot.captured_at_ms;
    let capture_elapsed_ms = snapshot.capture_elapsed_ms;
    let scanned_node_count = snapshot.scanned_node_count;
    let max_nodes = snapshot.max_nodes;
    let committed_node_count = snapshot.nodes.len();
    let google_account_avatar = webexplorer_google_account_avatar_from_memory(&snapshot);
    let receive_lag_ms = (now_epoch_ms() as i64).saturating_sub(captured_at_ms as i64);
    let auto_export_enabled = webexplorer_auto_export_enabled();
    let rust_commit_elapsed_us: u64;
    let dom_changed: bool;
    let export_result = {
        match state.lock() {
            Ok(mut state) => {
                let commit_started = Instant::now();
                let web_explorer = state.web_explorer_for_commit_url_mut(&commit_url);
                dom_changed = web_explorer.commit_dom_snapshot(snapshot);
                rust_commit_elapsed_us = commit_started.elapsed().as_micros() as u64;
                web_explorer.memory.last_commit_elapsed_us = rust_commit_elapsed_us;
                web_explorer.memory.last_receive_lag_ms = receive_lag_ms;
                if auto_export_enabled && dom_changed {
                    Some(build_webexplorer_clone_export(&web_explorer.memory_snapshot()))
                } else {
                    None
                }
            }
            Err(err) => {
                alpha_trace(
                    app,
                    "webexplorer.clone",
                    format!("state.lock.error {err}"),
                );
                return;
            }
        }
    };
    if let Some(export_result) = export_result {
        match export_result {
            Ok(result) => alpha_trace(
                app,
                "webexplorer.clone",
                format!(
                    "export.ok html={} json={} nodes={} frames={} text={} images={}",
                    result.html_path,
                    result.json_path,
                    result.exported_nodes,
                    result.exported_frames,
                    result.exported_text,
                    result.exported_images
                ),
            ),
            Err(err) => alpha_trace(app, "webexplorer.clone", format!("export.error {err}")),
        }
    }
    let _ = app.emit("webexplorer-dom-committed", json!({
        "url": commit_url.clone(),
        "capturedAtMs": captured_at_ms,
        "nodeCount": committed_node_count,
        "captureElapsedMs": capture_elapsed_ms,
        "rustCommitElapsedUs": rust_commit_elapsed_us,
        "receiveLagMs": receive_lag_ms,
        "scannedNodeCount": scanned_node_count,
        "maxNodes": max_nodes,
        "domChanged": dom_changed,
        "exportEnabled": auto_export_enabled,
        "source": "dom",
    }));
    if let Some(avatar_src) = google_account_avatar {
        alpha_trace(
            app,
            "webexplorer.google-auth",
            format!(
                "connected.memory-detected url={} avatar={}",
                commit_url,
                !avatar_src.is_empty()
            ),
        );
        let _ = app.emit("webexplorer-google-auth-connected", json!({
            "connected": true,
            "url": commit_url,
            "avatarSrc": avatar_src,
            "landingHidden": true,
            "sanitized": true,
            "source": "memory",
        }));
    }
}

