fn bloomberg_transcript_path() -> PathBuf {
    std::env::temp_dir().join("forge_bloomberg_live_transcript.txt")
}

fn reset_bloomberg_transcript() {
    let generation = BLOOMBERG_TRANSCRIPT_GENERATION.fetch_add(1, Ordering::SeqCst) + 1;
    let _ = enqueue_bloomberg_transcript_write(BloombergTranscriptWrite::Reset { generation });
    if let Ok(mut state) = bloomberg_transcript_state().lock() {
        *state = BloombergTranscriptState::default();
    }
}

fn append_bloomberg_transcript<R: Runtime>(
    app: &tauri::AppHandle<R>,
    encoded: &str,
) -> Result<(), String> {
    append_bloomberg_transcript_request(
        app,
        BloombergTranscriptRequest {
            text: None,
            encoded: Some(encoded.to_string()),
            key: None,
            source: Some("title-fallback".to_string()),
            language: None,
            start: None,
            end: None,
        },
    )
}

fn bloomberg_live_media_probe_script(_bridge_port: u16) -> String {
    r##"
(() => {
  const READY_PREFIX = "FORGE_BLOOMBERG_MEDIA_READY:";
  const TRANSCRIPT_PREFIX = "FORGE_BLOOMBERG_TRANSCRIPT:";
  const CROP_TOP_PX = 0;
  const BOTTOM_MASK_ID = "forge-bloomberg-bottom-crop-mask";
  const BOTTOM_MASK_HEIGHT = "0px";
  const PLAYER_STYLE_ID = "forge-bloomberg-player-style";
  const PANEL_COLOR = "#050505";
  const YOUTUBE_CHROME_SELECTORS = [
    ".ytp-title",
    ".ytp-title-text",
    ".ytp-title-link",
    ".ytp-title-channel",
    ".ytp-title-channel-logo",
    ".ytp-title-expanded-overlay",
    ".ytp-title-expanded-heading",
    ".ytp-chrome-top",
    ".ytp-chrome-bottom",
    ".ytp-gradient-top",
    ".ytp-gradient-bottom",
    ".ytp-youtube-button",
    ".ytp-watch-later-button",
    ".ytp-share-button",
    ".ytp-right-controls",
    ".ytp-left-controls",
    ".ytp-pause-overlay",
    ".ytp-bezel",
    ".ytp-bezel-icon",
    ".ytp-large-play-button",
    ".ytp-show-cards-title",
    ".ytp-watermark",
    ".ytp-ce-element",
    ".ytp-impression-link",
    ".ytp-cards-button",
    ".iv-branding",
  ];
  const YOUTUBE_CHROME_TEXT_PATTERNS = [
    /bloomberg\s+business/i,
    /bloomberg\s+television/i,
    /\byoutube\b/i,
  ];
  if (window.__forgeBloombergBaseProbeInstalled) {
    return;
  }
  window.__forgeBloombergBaseProbeInstalled = true;
  let readySent = false;
  let cropLoopStarted = false;
  let lastTranscriptText = "";
  let lastTranscriptAt = 0;

  const base64EncodeUtf8 = (value) => {
    try {
      const bytes = new TextEncoder().encode(String(value || ""));
      let binary = "";
      for (let i = 0; i < bytes.length; i += 1) binary += String.fromCharCode(bytes[i]);
      return btoa(binary);
    } catch (_) {
      try { return btoa(unescape(encodeURIComponent(String(value || "")))); } catch (_) { return ""; }
    }
  };

  const emitTranscriptText = (text, source = "caption") => {
    const clean = String(text || "").replace(/\s+/g, " ").trim();
    if (!clean || clean.length < 2) return;
    const now = Date.now();
    if (clean === lastTranscriptText && now - lastTranscriptAt < 8000) return;
    lastTranscriptText = clean;
    lastTranscriptAt = now;
    const payload = base64EncodeUtf8(clean.slice(0, 900));
    if (!payload) return;
    try {
      document.title = `${TRANSCRIPT_PREFIX}${payload}`;
    } catch (_) {}
  };

  const signalReady = (reason) => {
    if (readySent) return;
    readySent = true;
    try {
      document.title = `${READY_PREFIX}${reason}:${Date.now()}`;
    } catch (_) {}
  };

  const ensurePlayerStyle = () => {
    try {
      let style = document.getElementById(PLAYER_STYLE_ID);
      if (!style) {
        style = document.createElement("style");
        style.id = PLAYER_STYLE_ID;
        (document.head || document.documentElement).appendChild(style);
      }
      style.textContent = `
        html,
        body {
          width: 100% !important;
          height: 100% !important;
          max-height: 100% !important;
          margin: 0 !important;
          overflow: hidden !important;
          background: ${PANEL_COLOR} !important;
          scrollbar-width: none !important;
        }
        html::-webkit-scrollbar,
        body::-webkit-scrollbar,
        *::-webkit-scrollbar {
          width: 0 !important;
          height: 0 !important;
          display: none !important;
        }
        #player,
        #movie_player,
        .html5-video-player {
          width: 100% !important;
          height: 100% !important;
          overflow: hidden !important;
          background: ${PANEL_COLOR} !important;
        }
        ${YOUTUBE_CHROME_SELECTORS.join(",\n        ")} {
          position: fixed !important;
          inset: auto auto auto auto !important;
          top: -10000px !important;
          left: -10000px !important;
          right: auto !important;
          bottom: auto !important;
          transform: translateY(-240vh) !important;
          pointer-events: none !important;
          z-index: -1 !important;
        }
      `;
    } catch (_) {}
  };

  const moveNodeOffscreen = (node) => {
    if (!node || node === document.documentElement || node === document.body) return;
    try {
      node.setAttribute("aria-hidden", "true");
      node.style.removeProperty("display");
      node.style.removeProperty("visibility");
      node.style.removeProperty("opacity");
      node.style.setProperty("position", "fixed", "important");
      node.style.setProperty("inset", "auto auto auto auto", "important");
      node.style.setProperty("top", "-10000px", "important");
      node.style.setProperty("left", "-10000px", "important");
      node.style.setProperty("right", "auto", "important");
      node.style.setProperty("bottom", "auto", "important");
      node.style.setProperty("transform", "translateY(-240vh)", "important");
      node.style.setProperty("pointer-events", "none", "important");
      node.style.setProperty("z-index", "-1", "important");
    } catch (_) {}
  };

  const chromeTargetForTextNode = (node) => {
    try {
      return node.closest?.(
        ".ytp-title, .ytp-title-text, .ytp-title-channel, .ytp-chrome-top, " +
        ".ytp-chrome-bottom, .ytp-youtube-button, .ytp-impression-link, " +
        ".ytp-watermark, a, button"
      ) || node;
    } catch (_) {
      return node;
    }
  };

  const suppressYoutubeChrome = () => {
    try {
      for (const selector of YOUTUBE_CHROME_SELECTORS) {
        for (const node of document.querySelectorAll?.(selector) || []) {
          moveNodeOffscreen(node);
        }
      }
      const candidates = document.querySelectorAll?.(
        "#movie_player a, #movie_player button, #movie_player span, " +
        "#movie_player div, #movie_player img, #movie_player svg"
      ) || [];
      for (const node of candidates) {
        try {
          if (node.closest?.(".ytp-caption-window-container, .caption-window")) continue;
          const label = [
            node.textContent || "",
            node.getAttribute?.("aria-label") || "",
            node.getAttribute?.("title") || "",
            node.getAttribute?.("alt") || "",
            node.getAttribute?.("href") || "",
          ].join(" ").replace(/\s+/g, " ").trim();
          if (!label) continue;
          if (YOUTUBE_CHROME_TEXT_PATTERNS.some((pattern) => pattern.test(label))) {
            moveNodeOffscreen(chromeTargetForTextNode(node));
          }
        } catch (_) {}
      }
      for (const player of document.querySelectorAll?.(".html5-video-player, #movie_player") || []) {
        try {
          player.classList.remove("ytp-autohide-active");
          player.classList.add("ytp-autohide");
        } catch (_) {}
      }
    } catch (_) {}
  };

  const videos = () => Array.from(document.querySelectorAll?.("video") || []);

  const visibleCaptionText = () => {
    const selectors = [
      ".ytp-caption-segment",
      ".caption-window .captions-text",
      ".ytp-caption-window-container .captions-text",
    ];
    for (const selector of selectors) {
      const text = Array.from(document.querySelectorAll?.(selector) || [])
        .map((node) => node.textContent || "")
        .join(" ")
        .replace(/\s+/g, " ")
        .trim();
      if (text) return text;
    }
    return "";
  };

  const activeCueText = (video) => {
    try {
      const tracks = Array.from(video?.textTracks || []);
      const parts = [];
      for (const track of tracks) {
        try {
          if (track.mode === "disabled") track.mode = "hidden";
          const cues = Array.from(track.activeCues || []);
          for (const cue of cues) {
            const text = String(cue?.text || "").replace(/<[^>]*>/g, " ").trim();
            if (text) parts.push(text);
          }
        } catch (_) {}
      }
      return parts.join(" ").replace(/\s+/g, " ").trim();
    } catch (_) {
      return "";
    }
  };

  const probeTranscript = (video) => {
    const text = activeCueText(video) || visibleCaptionText();
    if (text) emitTranscriptText(text, "caption");
  };

  const applyPlayerCrop = () => {
    try {
      ensurePlayerStyle();
      suppressYoutubeChrome();
      const crop = `${Math.max(0, CROP_TOP_PX)}px`;
      const cropHeight = CROP_TOP_PX > 0 ? `calc(100% + ${crop})` : "100%";
      document.documentElement.style.setProperty("overflow", "hidden", "important");
      document.documentElement.style.setProperty("height", cropHeight, "important");
      document.body?.style?.setProperty("overflow", "hidden", "important");
      document.body?.style?.setProperty("height", cropHeight, "important");
      document.body?.style?.setProperty("min-height", cropHeight, "important");
      document.body?.style?.setProperty(
        "transform",
        CROP_TOP_PX > 0 ? `translateY(-${crop})` : "none",
        "important",
      );
      document.body?.style?.setProperty("transform-origin", "top left", "important");
    } catch (_) {}
  };

  const ensureBottomMask = () => {
    try {
      let mask = document.getElementById(BOTTOM_MASK_ID);
      if (!mask) {
        mask = document.createElement("div");
        mask.id = BOTTOM_MASK_ID;
        mask.setAttribute("aria-hidden", "true");
        (document.body || document.documentElement).appendChild(mask);
      }
      mask.style.setProperty("position", "fixed", "important");
      mask.style.setProperty("left", "0", "important");
      mask.style.setProperty("right", "0", "important");
      mask.style.setProperty("bottom", "0", "important");
      mask.style.setProperty("height", BOTTOM_MASK_HEIGHT, "important");
      mask.style.setProperty("display", BOTTOM_MASK_HEIGHT === "0px" ? "none" : "block", "important");
      mask.style.setProperty("background", PANEL_COLOR, "important");
      mask.style.setProperty("background-color", PANEL_COLOR, "important");
      mask.style.setProperty("z-index", "2147483647", "important");
      mask.style.setProperty("pointer-events", "none", "important");
    } catch (_) {}
  };

  const startCropLoop = () => {
    applyPlayerCrop();
    ensureBottomMask();
    if (cropLoopStarted) return;
    cropLoopStarted = true;
    setInterval(() => {
      applyPlayerCrop();
      ensureBottomMask();
      probeTranscript(pickVideo());
    }, 500);
  };

  const pickVideo = () => {
    const list = videos();
    list.sort((a, b) => {
      const ar = a.getBoundingClientRect?.() || { width: 0, height: 0 };
      const br = b.getBoundingClientRect?.() || { width: 0, height: 0 };
      return (br.width * br.height) - (ar.width * ar.height);
    });
    return list[0] || null;
  };

  const activateVideo = (video) => {
    if (!video) return;
    try {
      video.defaultMuted = false;
      video.muted = false;
      video.volume = 1;
      video.autoplay = true;
      video.playsInline = true;
      video.setAttribute("playsinline", "");
      Array.from(video.textTracks || []).forEach((track) => {
        try { if (track.mode === "disabled") track.mode = "hidden"; } catch (_) {}
      });
      video.play?.().catch?.(() => {});
    } catch (_) {}
  };

  window.__forgeBloombergPark = () => {
    try {
      videos().forEach((video) => {
        try {
          video.muted = true;
          video.pause?.();
        } catch (_) {}
      });
    } catch (_) {}
  };
  window.__forgeBloombergResume = () => {
    try {
      activateVideo(pickVideo());
      suppressYoutubeChrome();
      setTimeout(() => signalReady("base-resume"), 700);
    } catch (_) {}
  };
  window.__forgeBloombergForceReleaseSplash = window.__forgeBloombergResume;

  const tick = () => {
    startCropLoop();
    suppressYoutubeChrome();
    const video = pickVideo();
    if (video) {
      activateVideo(video);
      probeTranscript(video);
      if (Number(video.readyState || 0) >= 2 || Number(video.videoWidth || 0) > 0) {
        signalReady("base-video");
        return;
      }
    }
    setTimeout(tick, 500);
  };
  window.__forgeBloombergProbeTick = tick;

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => {
      startCropLoop();
      tick();
    }, { once: true });
  } else {
    startCropLoop();
    tick();
  }
})();
"##
    .to_string()
}

fn bloomberg_live_target_matches(url: &Url) -> bool {
    let host = url.host_str().unwrap_or_default().to_ascii_lowercase();
    if !host.ends_with("youtube.com") && !host.ends_with("youtube-nocookie.com") && host != "youtu.be" {
        return false;
    }
    if host == "youtu.be" {
        return url.path().trim_start_matches('/').eq(BLOOMBERG_YOUTUBE_VIDEO_ID);
    }
    if url.path() == format!("/embed/{BLOOMBERG_YOUTUBE_VIDEO_ID}") {
        return true;
    }
    url.path() == "/watch"
        && url
            .query_pairs()
            .any(|(key, value)| key == "v" && value == BLOOMBERG_YOUTUBE_VIDEO_ID)
}

fn bloomberg_live_target_matches_str(raw_url: &str) -> bool {
    Url::parse(raw_url)
        .ok()
        .is_some_and(|url| bloomberg_live_target_matches(&url))
}

fn bloomberg_live_current_matches_target(url: &Url) -> bool {
    if !bloomberg_live_target_matches(url) {
        return false;
    }
    if url.path() != format!("/embed/{BLOOMBERG_YOUTUBE_VIDEO_ID}") {
        return false;
    }
    let mut has_controls_off = false;
    let mut has_fullscreen_off = false;
    for (key, value) in url.query_pairs() {
        if key == "controls" && value == "0" {
            has_controls_off = true;
        }
        if key == "fs" && value == "0" {
            has_fullscreen_off = true;
        }
    }
    has_controls_off && has_fullscreen_off
}

fn sync_bloomberg_live_native<R: Runtime>(
    app: &tauri::AppHandle<R>,
    bounds: WebExplorerMemoryBounds,
    force_reload: bool,
    start_media: bool,
) -> Result<(), String> {
    let bridge_port = ensure_webexplorer_bridge_server(app)?;
    if !bounds.x.is_finite()
        || !bounds.y.is_finite()
        || !bounds.width.is_finite()
        || !bounds.height.is_finite()
    {
        return Err("invalid bloomberg bounds: non-finite value".to_string());
    }
    if bounds.width < 2.0 || bounds.height < 2.0 {
        return Err(format!(
            "invalid bloomberg bounds: {}x{}",
            bounds.width, bounds.height
        ));
    }
    let mut visible_bounds = WebExplorerMemoryBounds {
        x: bounds.x.round(),
        y: bounds.y.round(),
        width: bounds.width.round().max(2.0),
        height: bounds.height.round().max(2.0),
    };
    if start_media {
        visible_bounds = guarded_native_visible_bounds(visible_bounds);
    }
    let target_url =
        Url::parse(BLOOMBERG_LIVE_URL).map_err(|e| format!("invalid bloomberg url: {e}"))?;
    BLOOMBERG_NATIVE_SHOULD_START.store(start_media, Ordering::SeqCst);
    let position = LogicalPosition::new(visible_bounds.x, visible_bounds.y);
    let size = LogicalSize::new(visible_bounds.width, visible_bounds.height);
    alpha_trace(
        app,
        "trading.bloomberg.native",
        format!(
            "backend.begin url={} x={} y={} w={} h={} force_reload={}",
            target_url, position.x, position.y, size.width, size.height, force_reload
        ),
    );

    if let Some(webview) = app.get_webview(BLOOMBERG_CHILD_LABEL) {
        let current = webview.url().ok();
        let current_is_loader = current
            .as_ref()
            .is_some_and(|url| url.as_str().contains("bloomberg-loader.html"));
        let current_matches_target = current
            .as_ref()
            .is_some_and(|url| bloomberg_live_current_matches_target(url));
        let should_recreate = force_reload || (!current_is_loader && !current_matches_target);
        let (already_applied, should_resume) = bloomberg_native_runtime()
            .lock()
            .ok()
            .map(|state| {
                let same_bounds = state
                    .bounds
                    .as_ref()
                    .is_some_and(|last| native_bounds_equal(last, &visible_bounds));
                (
                    state.visible
                        && !state.parked
                        && state.url_key == BLOOMBERG_LIVE_URL
                        && same_bounds,
                    !state.visible || state.parked,
                )
            })
            .unwrap_or((false, true));
        alpha_trace(
            app,
            "trading.bloomberg.native",
            format!(
                "present.update existing=true current_url={} recreate={}",
                current
                    .as_ref()
                    .map(|url| url.to_string())
                    .unwrap_or_else(|| "<unknown>".to_string()),
                should_recreate
            ),
        );
        if should_recreate {
            BLOOMBERG_NATIVE_PAGE_READY.store(false, Ordering::SeqCst);
            BLOOMBERG_NATIVE_VIEWER_PREPARED.store(false, Ordering::SeqCst);
            BLOOMBERG_NATIVE_MEDIA_READY.store(false, Ordering::SeqCst);
            reset_bloomberg_transcript();
            webview.close().map_err(|e| e.to_string())?;
            if let Ok(mut state) = bloomberg_native_runtime().lock() {
                *state = NativeWebviewRuntimeState::default();
            }
            alpha_trace(
                app,
                "trading.bloomberg.native",
                "present.update.closed-for-recreate",
            );
        } else if already_applied {
            alpha_trace(app, "trading.bloomberg.native", "present.update.noop");
            return Ok(());
        } else {
            set_native_webview_bounds(&webview, &visible_bounds)?;
            let _ = webview.set_auto_resize(false);
            if start_media {
                let _ = webview.show();
                if current_is_loader {
                    let _ = webview.eval(bloomberg_start_script());
                } else if should_resume {
                    let _ = webview.eval("window.__forgeBloombergResume?.()");
                }
            } else {
                let _ = webview.hide();
            }
            if let Ok(mut state) = bloomberg_native_runtime().lock() {
                state.visible = start_media;
                state.parked = !start_media;
                state.url_key = BLOOMBERG_LIVE_URL.to_string();
                state.bounds = start_media.then_some(visible_bounds.clone());
            }
            alpha_trace(app, "trading.bloomberg.native", "present.update.ok");
            return Ok(());
        }
    }

    reset_bloomberg_transcript();
    BLOOMBERG_NATIVE_PAGE_READY.store(false, Ordering::SeqCst);
    BLOOMBERG_NATIVE_VIEWER_PREPARED.store(false, Ordering::SeqCst);
    BLOOMBERG_NATIVE_MEDIA_READY.store(false, Ordering::SeqCst);
    let title_app = app.clone();
    let load_app = app.clone();
    let probe_script = Arc::new(bloomberg_live_media_probe_script(bridge_port));
    let prepared_emitted = Arc::new(AtomicBool::new(false));
    let ready_emitted = Arc::new(AtomicBool::new(false));
    let prepared_emitted_for_title = prepared_emitted.clone();
    let ready_emitted_for_title = ready_emitted.clone();
    let prepared_bounds_for_title = visible_bounds.clone();
    let ready_bounds_for_title = visible_bounds.clone();
    let load_bounds = visible_bounds.clone();
    let probe_script_for_load = probe_script.clone();
    let builder = tune_native_webview_builder(WebviewBuilder::new(
        BLOOMBERG_CHILD_LABEL,
        WebviewUrl::App("bloomberg-loader.html".into()),
    ), true)
    .initialization_script(probe_script.as_str())
    .on_navigation(|url| {
        let raw = url.as_str();
        raw.contains("bloomberg-loader.html")
            || raw == "about:blank"
            || bloomberg_live_target_matches(url)
    })
    .on_new_window(|_, _| tauri::webview::NewWindowResponse::Deny)
    .on_document_title_changed(move |webview, title| {
        if title.starts_with(BLOOMBERG_NAVIGATING_TITLE_PREFIX) {
            BLOOMBERG_NATIVE_PAGE_READY.store(false, Ordering::SeqCst);
            BLOOMBERG_NATIVE_VIEWER_PREPARED.store(false, Ordering::SeqCst);
            BLOOMBERG_NATIVE_MEDIA_READY.store(false, Ordering::SeqCst);
            alpha_trace(
                &title_app,
                "trading.bloomberg.native",
                format!("navigation.armed title={title}"),
            );
            return;
        }
        if let Some(encoded) = title.strip_prefix(BLOOMBERG_TRANSCRIPT_TITLE_PREFIX) {
            if let Err(err) = append_bloomberg_transcript(&title_app, encoded) {
                alpha_trace(
                    &title_app,
                    "trading.bloomberg.native",
                    format!("transcript.append.error {err}"),
                );
            }
            return;
        }
        if title.starts_with(BLOOMBERG_VIEWER_PREPARED_TITLE_PREFIX) {
            if prepared_emitted_for_title.swap(true, Ordering::SeqCst) {
                return;
            }
            BLOOMBERG_NATIVE_VIEWER_PREPARED.store(true, Ordering::SeqCst);
            if let Err(err) = set_native_webview_bounds(&webview, &prepared_bounds_for_title) {
                alpha_trace(
                    &title_app,
                    "trading.bloomberg.native",
                    format!("viewer.prepared.bounds.error {err}"),
                );
                return;
            }
            let _ = webview.set_auto_resize(false);
            if let Err(err) = webview.show() {
                alpha_trace(
                    &title_app,
                    "trading.bloomberg.native",
                    format!("viewer.prepared.show.error {err}"),
                );
                return;
            }
            alpha_trace(
                &title_app,
                "trading.bloomberg.native",
                format!("viewer.prepared title={title}"),
            );
            return;
        }
        if !title.starts_with(BLOOMBERG_MEDIA_READY_TITLE_PREFIX) {
            return;
        }
        if ready_emitted_for_title.swap(true, Ordering::SeqCst) {
            return;
        }
        BLOOMBERG_NATIVE_MEDIA_READY.store(true, Ordering::SeqCst);
        if let Err(err) = set_native_webview_bounds(&webview, &ready_bounds_for_title) {
            alpha_trace(
                &title_app,
                "trading.bloomberg.native",
                format!("media.ready.bounds.error {err}"),
            );
            return;
        }
        let _ = webview.show();
        let _ = webview.set_auto_resize(false);
        alpha_trace(
            &title_app,
            "trading.bloomberg.native",
            format!("media.ready title={title}"),
        );
        let _ = title_app.emit(
            "bloomberg-live-media-ready",
            json!({
                "state": "media-ready",
                "url": BLOOMBERG_LIVE_URL,
                "detail": title,
            }),
        );
    })
    .on_page_load(move |webview, payload| {
        let page_url = payload.url().to_string();
        alpha_trace(
            &load_app,
            "trading.bloomberg.native",
            format!("page_load event={:?} url={}", payload.event(), page_url),
        );
        let is_loader = page_url.contains("bloomberg-loader.html");
        let is_bloomberg_live = bloomberg_live_target_matches_str(&page_url);
        if matches!(payload.event(), tauri::webview::PageLoadEvent::Finished) && is_loader {
            if BLOOMBERG_NATIVE_SHOULD_START.load(Ordering::SeqCst) {
                let _ = webview.eval(bloomberg_start_script());
                alpha_trace(
                    &load_app,
                    "trading.bloomberg.native",
                    "page_load.loader.start-media",
                );
            } else {
                alpha_trace(
                    &load_app,
                    "trading.bloomberg.native",
                    "page_load.loader.prewarmed",
                );
            }
            return;
        }
        if matches!(payload.event(), tauri::webview::PageLoadEvent::Started) && is_bloomberg_live {
            BLOOMBERG_NATIVE_PAGE_READY.store(false, Ordering::SeqCst);
            BLOOMBERG_NATIVE_VIEWER_PREPARED.store(false, Ordering::SeqCst);
            BLOOMBERG_NATIVE_MEDIA_READY.store(false, Ordering::SeqCst);
            let _ = webview.eval(probe_script_for_load.as_str());
            let _ = webview.show();
            alpha_trace(
                &load_app,
                "trading.bloomberg.native",
                "page_load.started.show-with-overlay",
            );
            return;
        }
        if matches!(payload.event(), tauri::webview::PageLoadEvent::Finished) {
            let eval_result = webview.eval(probe_script_for_load.as_str());
            match eval_result {
                Ok(_) => alpha_trace(
                    &load_app,
                    "trading.bloomberg.native",
                    "page_load.media_probe.eval.ok",
                ),
                Err(err) => alpha_trace(
                    &load_app,
                    "trading.bloomberg.native",
                    format!("page_load.media_probe.eval.error {err}"),
                ),
            }
            if is_bloomberg_live && !is_loader {
                BLOOMBERG_NATIVE_PAGE_READY.store(true, Ordering::SeqCst);
                let watchdog_webview = webview.clone();
                let watchdog_app = load_app.clone();
                thread::spawn(move || {
                    thread::sleep(Duration::from_millis(2200));
                    if BLOOMBERG_NATIVE_MEDIA_READY.load(Ordering::SeqCst) {
                        return;
                    }
                    let _ = watchdog_webview.eval(
                        "window.__forgeBloombergResume?.(); window.__forgeBloombergProbeTick?.('backend-watchdog');",
                    );
                    alpha_trace(
                        &watchdog_app,
                        "trading.bloomberg.native",
                        "media.ready.watchdog.probe-nudge",
                    );
                });
                if let Err(err) = set_native_webview_bounds(&webview, &load_bounds) {
                    alpha_trace(
                        &load_app,
                        "trading.bloomberg.native",
                        format!("page_load.finished.bounds.error {err}"),
                    );
                    return;
                }
                let _ = webview.set_auto_resize(false);
                if let Err(err) = webview.show() {
                    alpha_trace(
                        &load_app,
                        "trading.bloomberg.native",
                        format!("page_load.finished.show.error {err}"),
                    );
                } else {
                    alpha_trace(
                        &load_app,
                        "trading.bloomberg.native",
                        "page_load.finished.show-after-probe",
                    );
                }
            }
        }
    });
    let main = app
        .get_window("main")
        .ok_or_else(|| "window 'main' not found".to_string())?;
    alpha_trace(
        app,
        "trading.bloomberg.native",
        format!("present.create.begin main_webviews={}", main.webviews().len()),
    );
    let webview = main
        .add_child(builder, position, size)
        .map_err(|e| e.to_string())?;
    let _ = webview.set_auto_resize(false);
    if start_media {
        let _ = webview.show();
    } else {
        let _ = webview.hide();
    }
    tune_native_platform_webview(app, BLOOMBERG_CHILD_LABEL, "bloomberg-media");
    alpha_trace(
        app,
        "trading.bloomberg.native",
        format!(
            "present.create.ok url={} main_webviews={}",
            target_url,
            main.webviews().len()
        ),
    );
    if let Ok(mut state) = bloomberg_native_runtime().lock() {
        state.visible = start_media;
        state.parked = !start_media;
        state.url_key = BLOOMBERG_LIVE_URL.to_string();
        state.bounds = start_media.then_some(visible_bounds);
    }
    Ok(())
}

#[tauri::command]
async fn bloomberg_live_native_present<R: Runtime>(
    app: tauri::AppHandle<R>,
    bounds: WebExplorerMemoryBounds,
    force_reload: Option<bool>,
    kernel: tauri::State<'_, Mutex<forge_kernel::ForgeKernel>>,
) -> Result<(), String> {
    let reload = force_reload.unwrap_or(false);
    let store_path = forge_store_path_from_app(&app);
    let _proof = forge_fbc_guard_sensitive_action(
        &kernel,
        store_path.as_deref(),
        "bloomberg_live_native_present",
        json!({ "bounds": &bounds, "forceReload": reload }),
    )?;
    let generation = BLOOMBERG_PRESENT_GENERATION.fetch_add(1, Ordering::SeqCst) + 1;
    tauri::async_runtime::spawn_blocking(move || {
        if BLOOMBERG_PRESENT_GENERATION.load(Ordering::SeqCst) != generation {
            alpha_trace(
                &app,
                "trading.bloomberg.native",
                format!("present.coalesced.stale generation={generation}"),
            );
            return Ok(());
        }
        sync_bloomberg_live_native(&app, bounds, reload, true)
    })
        .await
        .map_err(|e| e.to_string())?
}

#[tauri::command]
async fn bloomberg_live_native_prewarm<R: Runtime>(app: tauri::AppHandle<R>) -> Result<(), String> {
    alpha_trace(
        &app,
        "trading.bloomberg.native",
        "prewarm.skipped create-on-open",
    );
    Ok(())
}

#[tauri::command]
fn bloomberg_live_native_hide<R: Runtime>(
    app: tauri::AppHandle<R>,
    kernel: tauri::State<'_, Mutex<forge_kernel::ForgeKernel>>,
) -> Result<(), String> {
    let store_path = forge_store_path_from_app(&app);
    let _proof = forge_fbc_guard_sensitive_action(
        &kernel,
        store_path.as_deref(),
        "bloomberg_live_native_hide",
        json!({ "target": BLOOMBERG_CHILD_LABEL }),
    )?;
    BLOOMBERG_PRESENT_GENERATION.fetch_add(1, Ordering::SeqCst);
    if let Some(webview) = app.get_webview(BLOOMBERG_CHILD_LABEL) {
        alpha_trace(&app, "trading.bloomberg.native", "hide.park.begin");
        let _ = webview.eval("window.__forgeBloombergPark?.()");
        let _ = set_native_webview_bounds(
            &webview,
            &WebExplorerMemoryBounds {
                x: -12_000.0,
                y: -12_000.0,
                width: 2.0,
                height: 2.0,
            },
        );
        let _ = webview.set_auto_resize(false);
        let _ = webview.hide();
        if let Ok(mut state) = bloomberg_native_runtime().lock() {
            state.visible = false;
            state.parked = true;
            state.bounds = None;
            if state.url_key.is_empty() {
                state.url_key = BLOOMBERG_LIVE_URL.to_string();
            }
        }
        alpha_trace(&app, "trading.bloomberg.native", "hide.park.ok");
    } else {
        alpha_trace(&app, "trading.bloomberg.native", "hide.noop.no-webview");
    }
    Ok(())
}

#[tauri::command]
fn bloomberg_live_transcript_start() -> Result<JsonValue, String> {
    reset_bloomberg_transcript();
    BLOOMBERG_TRANSCRIPT_RECORDING.store(true, Ordering::SeqCst);
    let path = bloomberg_transcript_path();
    Ok(json!({
        "path": path.to_string_lossy(),
        "lineCount": 0,
        "text": "",
        "recording": true,
        "startedAtMs": now_epoch_ms(),
    }))
}

#[tauri::command]
fn bloomberg_live_transcript_stop() -> Result<JsonValue, String> {
    BLOOMBERG_TRANSCRIPT_RECORDING.store(false, Ordering::SeqCst);
    let mut snapshot = bloomberg_live_transcript_snapshot()?;
    if let Some(object) = snapshot.as_object_mut() {
        object.insert("recording".to_string(), json!(false));
        object.insert("stoppedAtMs".to_string(), json!(now_epoch_ms()));
    }
    Ok(snapshot)
}

#[tauri::command]
fn bloomberg_live_transcript_reset() -> Result<JsonValue, String> {
    BLOOMBERG_TRANSCRIPT_RECORDING.store(false, Ordering::SeqCst);
    reset_bloomberg_transcript();
    let path = bloomberg_transcript_path();
    Ok(json!({
        "path": path.to_string_lossy(),
        "lineCount": 0,
        "text": "",
        "truncated": false,
        "source": "reset",
        "recording": false,
        "resetAtMs": now_epoch_ms(),
    }))
}

#[tauri::command]
fn bloomberg_live_transcript_snapshot() -> Result<JsonValue, String> {
    let path = bloomberg_transcript_path();
    if let Ok(state) = bloomberg_transcript_state().lock() {
        if !state.recent_lines.is_empty() {
            return Ok(json!({
                "path": path.to_string_lossy(),
                "lineCount": state.total_lines,
                "text": state.recent_lines.iter().cloned().collect::<Vec<_>>().join("\n"),
                "truncated": true,
                "source": "ring-buffer",
                "recording": BLOOMBERG_TRANSCRIPT_RECORDING.load(Ordering::SeqCst),
            }));
        }
    }
    let mut file = match std::fs::File::open(&path) {
        Ok(file) => file,
        Err(err) if err.kind() == std::io::ErrorKind::NotFound => {
            return Ok(json!({
                "path": path.to_string_lossy(),
                "lineCount": 0,
                "text": "",
                "truncated": false,
                "source": "empty",
                "recording": BLOOMBERG_TRANSCRIPT_RECORDING.load(Ordering::SeqCst),
            }));
        }
        Err(err) => return Err(format!("read bloomberg transcript '{}': {err}", path.display())),
    };
    let len = file.metadata().map_err(|err| {
        format!("stat bloomberg transcript '{}': {err}", path.display())
    })?.len();
    let start = len.saturating_sub(160 * 1024);
    file.seek(SeekFrom::Start(start)).map_err(|err| {
        format!("seek bloomberg transcript '{}': {err}", path.display())
    })?;
    let mut text = String::new();
    file.read_to_string(&mut text).map_err(|err| {
        format!("read bloomberg transcript '{}': {err}", path.display())
    })?;
    if start > 0 {
        if let Some((_, tail)) = text.split_once('\n') {
            text = tail.to_string();
        }
    }
    let line_count = text.lines().count();
    Ok(json!({
        "path": path.to_string_lossy(),
        "lineCount": line_count,
        "text": text,
        "truncated": start > 0,
        "source": "file-tail",
        "recording": BLOOMBERG_TRANSCRIPT_RECORDING.load(Ordering::SeqCst),
    }))
}

#[tauri::command]
fn webexplorer_set_scope(
    scope: String,
    state: tauri::State<'_, Mutex<ForgeAppState>>,
) -> Result<WebExplorerSnapshot, String> {
    let mut state = state.lock().map_err(|e| e.to_string())?;
    let normalized = state.set_web_explorer_scope(&scope);
    Ok(state.web_explorer_for_scope(Some(normalized)).snapshot())
}

#[tauri::command]
fn webexplorer_session_snapshot(
    state: tauri::State<'_, Mutex<ForgeAppState>>,
) -> Result<WebExplorerSnapshot, String> {
    let state = state.lock().map_err(|e| e.to_string())?;
    Ok(state.active_web_explorer().snapshot())
}

#[tauri::command]
fn webexplorer_navigate(
    input: String,
    app: tauri::AppHandle,
    state: tauri::State<'_, Mutex<ForgeAppState>>,
) -> Result<WebExplorerSnapshot, String> {
    let mut state = state.lock().map_err(|e| e.to_string())?;
    let snapshot = state.active_web_explorer_mut().commit(&input)?;
    drop(state);
    kick_webexplorer_google_fetch_fallback(app, snapshot.current_url.clone());
    Ok(snapshot)
}

