#[tauri::command]
fn webexplorer_memory_ping(
    url: String,
    stage: String,
    node_count: Option<usize>,
    app: tauri::AppHandle,
) -> Result<(), String> {
    webexplorer_memory_ping_internal(&app, url, stage, node_count);
    Ok(())
}

