#[tauri::command]
async fn create_forge_pending_job(
    request: ForgePendingUploadRequest,
    state: tauri::State<'_, Mutex<ForgeAppState>>,
) -> Result<ForgeJobEntry, String> {
    let ForgePendingUploadRequest {
        job_id,
        file_name,
        bytes,
        files,
        kind,
        title,
        allow_empty,
    } = request;
    let allow_empty = allow_empty.unwrap_or(false);
    let requested_job_id = job_id
        .as_deref()
        .map(str::trim)
        .filter(|v| !v.is_empty())
        .map(str::to_string);
    if let Some(job_id) = requested_job_id.as_deref() {
        if !safe_forge_job_id(job_id) {
            return Err("invalid Forge job id".to_string());
        }
    }
    let mut files = if let Some(files) = files {
        files
    } else {
        vec![ForgePendingUploadFile {
            file_name: file_name.unwrap_or_else(|| "upload.csv".to_string()),
            bytes: bytes.unwrap_or_default(),
        }]
    };
    files.retain(|file| !file.bytes.is_empty());
    if files.is_empty() && !allow_empty {
        return Err("cannot create pending session from empty uploads".to_string());
    }
    let store_path = {
        let app_state = state.lock().map_err(|e| e.to_string())?;
        app_state.store_path.clone()
    };
    let jobs_dir = store_path.join("jobs");
    let all_job_dirs = forge_job_mirror_dirs(&jobs_dir);
    let uploads_dir = store_path.join("uploads");
    std::fs::create_dir_all(&jobs_dir).map_err(|e| format!("create jobs dir: {e}"))?;
    std::fs::create_dir_all(&uploads_dir).map_err(|e| format!("create uploads dir: {e}"))?;

    let existing_manifest = if let Some(job_id) = requested_job_id.as_deref() {
        let (_manifest_path, bytes) = read_forge_job_manifest_from_dirs(job_id, &all_job_dirs)?;
        Some(
            serde_json::from_slice::<JsonValue>(&bytes)
                .map_err(|e| format!("decode existing Forge job manifest: {e}"))?,
        )
    } else {
        None
    };

    let mut session_hash = files.len() as u64;
    let mut total_bytes = 0usize;
    for file in &files {
        session_hash = session_hash
            .wrapping_mul(0x517cc1b727220a95)
            .wrapping_add(quick_file_hash(&file.bytes));
        total_bytes += file.bytes.len();
    }
    let job_id = requested_job_id.unwrap_or_else(|| format!("pending-{}-{session_hash:016x}", now_epoch_ms()));
    let upload_dir = uploads_dir.join(&job_id);
    std::fs::create_dir_all(&upload_dir).map_err(|e| format!("create upload job dir: {e}"))?;
    let mut file_paths = Vec::with_capacity(files.len());
    let mut original_file_names = Vec::with_capacity(files.len());
    let mut file_summaries = Vec::with_capacity(files.len());
    for (idx, file) in files.iter().enumerate() {
        let safe_name = safe_upload_file_name(&file.file_name);
        let numbered_name = format!("{:02}_{}", idx + 1, safe_name);
        let file_path = upload_dir.join(numbered_name);
        std::fs::write(&file_path, &file.bytes)
            .map_err(|e| format!("write uploaded file '{}': {e}", file_path.display()))?;
        let ext = Path::new(&file.file_name)
            .extension()
            .and_then(|v| v.to_str())
            .unwrap_or("")
            .to_ascii_lowercase();
        let line_count = file.bytes.iter().filter(|&&b| b == b'\n').count()
            + usize::from(!file.bytes.is_empty());
        let header = if ext == "csv" || ext == "txt" {
            let first_line = file
                .bytes
                .split(|&b| b == b'\n')
                .next()
                .unwrap_or(&[])
                .iter()
                .copied()
                .filter(|b| *b != b'\r')
                .take(220)
                .collect::<Vec<u8>>();
            String::from_utf8_lossy(&first_line).to_string()
        } else {
            String::new()
        };
        let columns = if ext == "csv" && !header.is_empty() {
            header
                .split(',')
                .map(str::trim)
                .filter(|v| !v.is_empty())
                .take(32)
                .map(str::to_string)
                .collect::<Vec<_>>()
        } else {
            Vec::new()
        };
        file_summaries.push(json!({
            "name": file.file_name,
            "path": file_path.display().to_string(),
            "extension": ext,
            "bytes": file.bytes.len(),
            "line_count_estimate": line_count,
            "columns": columns,
            "raw_content_included": false
        }));
        file_paths.push(file_path.display().to_string());
        original_file_names.push(file.file_name.clone());
    }
    let primary_file_path = file_paths.first().cloned().unwrap_or_default();
    let primary_file_name = original_file_names
        .first()
        .cloned()
        .unwrap_or_else(|| "Empty session".to_string());
    let title = title
        .as_deref()
        .map(str::trim)
        .filter(|v| !v.is_empty())
        .map(str::to_string)
        .or_else(|| {
            existing_manifest
                .as_ref()
                .and_then(|m| m.get("title"))
                .and_then(|v| v.as_str())
                .map(str::to_string)
        })
        .unwrap_or_else(|| primary_file_name.clone());
    let file_count = file_paths.len() as u64;

    let kind = kind
        .filter(|v| !v.trim().is_empty())
        .or_else(|| {
            existing_manifest
                .as_ref()
                .and_then(|m| m.get("kind"))
                .and_then(|v| v.as_str())
                .map(str::to_string)
        })
        .unwrap_or_else(|| {
            if file_count == 0 {
                "ActCode_session".to_string()
            } else {
                "alpha_strategy_from_csv".to_string()
            }
        });
    let log_path = jobs_dir.join(format!("{job_id}.log"));
    let modified_ms = now_epoch_ms() as u64;
    let created_ms = existing_manifest
        .as_ref()
        .and_then(|m| m.get("created_ms"))
        .and_then(|v| v.as_u64())
        .unwrap_or(modified_ms);
    let pinned = existing_manifest
        .as_ref()
        .and_then(|m| m.get("pinned"))
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let archived = existing_manifest
        .as_ref()
        .and_then(|m| m.get("archived"))
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let actcode_hint = if file_count == 0 {
        json!({
            "tool": "forge_session",
            "arguments": {
                "job_id": job_id,
                "inputs": []
            }
        })
    } else {
        json!({
            "tool": "forge_alpha_strategy_from_csv",
            "arguments": {
                "csv_path": primary_file_path,
                "csv_paths": file_paths
            }
        })
    };
    let manifest_kind = kind.clone();
    let manifest = json!({
        "job_id": job_id,
        "title": title.clone(),
        "kind": manifest_kind,
        "status": "pending",
        "source": "ui_upload",
        "file_path": primary_file_path,
        "file_paths": file_paths,
        "original_file_name": primary_file_name,
        "original_file_names": original_file_names,
        "file_summaries": file_summaries,
        "file_hash": session_hash,
        "file_count": file_count,
        "bytes": total_bytes,
        "bars": null,
        "pinned": pinned,
        "archived": archived,
        "protected": true,
        "history_protected": true,
        "strategy_hash": null,
        "agents": [],
        "context_accounting": {
            "metric": "llm_context_avoided",
            "token_mode": "estimated",
            "tokenizer": "model_unknown",
            "csv_bytes": total_bytes,
            "log_bytes": 0,
            "avoided_bytes": total_bytes,
            "estimated_tokens": (total_bytes + 3) / 4,
            "exact_tokens": null,
            "note": "Pending UI upload: no ActCode agent has claimed this job yet."
        },
        "created_ms": created_ms,
        "log_path": log_path.display().to_string(),
        "actcode_hint": actcode_hint
    });
    let manifest_bytes = serde_json::to_vec_pretty(&manifest)
        .map_err(|e| format!("encode pending job manifest: {e}"))?;
    write_forge_job_manifest_to_dirs(&job_id, &manifest_bytes, &all_job_dirs)?;
    let existing_log = if existing_manifest.is_some() {
        std::fs::read_to_string(&log_path).unwrap_or_default()
    } else {
        String::new()
    };
    let pending_log = if existing_manifest.is_some() {
        format!(
            "{}{}pending upload session updated\nfiles={}\nprimary={}\nbytes={}\nwaiting for ActCode agent to claim calculation\n",
            existing_log,
            if existing_log.is_empty() || existing_log.ends_with('\n') { "" } else { "\n" },
            file_count,
            primary_file_path,
            total_bytes
        )
    } else if file_count == 0 {
        "pending empty session created\nfiles=0\nprimary=\nbytes=0\nwaiting for ActCode agent to claim calculation\n".to_string()
    } else {
        format!(
            "pending upload session created\nfiles={}\nprimary={}\nbytes={}\nwaiting for ActCode agent to claim calculation\n",
            file_count,
            primary_file_path,
            total_bytes
        )
    };
    write_forge_job_log_to_dirs(&job_id, &pending_log, &all_job_dirs)?;

    let unified_job = forge_job_runtime::ForgeUnifiedJob::from_manifest(
        &job_id,
        &kind,
        "pending",
        &manifest,
        modified_ms,
    );
    let _ = forge_job_runtime::append_job_ledger_event(&store_path, "created", modified_ms, &unified_job);

    Ok(ForgeJobEntry {
        job: unified_job,
        job_id,
        title: Some(title),
        status: "pending".to_string(),
        kind,
        file_path: primary_file_path,
        file_count: Some(file_count),
        pinned: Some(pinned),
        strategy_hash: None,
        bars: None,
        agents: None,
        context_accounting: Some(json!({
            "metric": "llm_context_avoided",
            "token_mode": "estimated",
            "tokenizer": "model_unknown",
            "csv_bytes": total_bytes,
            "log_bytes": 0,
            "avoided_bytes": total_bytes,
            "estimated_tokens": (total_bytes + 3) / 4,
            "exact_tokens": null,
            "note": "Pending UI upload: no ActCode agent has claimed this job yet."
        })),
        performance: None,
        last_modified_ms: modified_ms,
    })
}

#[tauri::command]
async fn list_forge_jobs(
    limit: Option<usize>,
    state: tauri::State<'_, Mutex<ForgeAppState>>,
    _kernel: tauri::State<'_, Mutex<forge_kernel::ForgeKernel>>,
) -> Result<Vec<ForgeJobEntry>, String> {
    let store_path = forge_store_path_from_state(&state)?;
    let jobs_dir = store_path.join("jobs");
    let all_job_dirs = forge_job_mirror_dirs(&jobs_dir);
    let mut paths_by_job = std::collections::HashMap::<String, (SystemTime, u64, PathBuf)>::new();
    let mut unreadable_dirs = Vec::new();
    for dir in &all_job_dirs {
        let entries = match std::fs::read_dir(dir) {
            Ok(entries) => entries,
            Err(err) if err.kind() == std::io::ErrorKind::NotFound => continue,
            Err(err) => {
                unreadable_dirs.push(format!("{} ({err})", dir.display()));
                continue;
            }
        };
        for entry in entries.flatten() {
            let path = entry.path();
            if path.extension().and_then(|s| s.to_str()) != Some("json") {
                continue;
            }
            let metadata = match entry.metadata() {
                Ok(metadata) => metadata,
                Err(_) => continue,
            };
            let modified = metadata.modified().unwrap_or(SystemTime::UNIX_EPOCH);
            let len = metadata.len();
            let fallback_id = path
                .file_stem()
                .and_then(|s| s.to_str())
                .unwrap_or("")
                .to_string();
            if fallback_id.is_empty() {
                continue;
            }
            match paths_by_job.get(&fallback_id) {
                Some((known_modified, _, _)) if *known_modified >= modified => {}
                _ => {
                    paths_by_job.insert(fallback_id, (modified, len, path));
                }
            }
        }
    }
    if paths_by_job.is_empty() && !unreadable_dirs.is_empty() {
        return Err(format!(
            "read Forge jobs dirs failed: {}",
            unreadable_dirs.join("; ")
        ));
    }
    let max_items = limit.unwrap_or(30).clamp(1, 200);
    let mut signature_parts = paths_by_job
        .iter()
        .map(|(job_id, (modified, len, path))| {
            let modified_ms = modified
                .duration_since(UNIX_EPOCH)
                .unwrap_or_default()
                .as_millis();
            format!("{job_id}:{modified_ms}:{len}:{}", path.display())
        })
        .collect::<Vec<_>>();
    signature_parts.sort();
    let signature = signature_parts.join("|");
    if let Some(entries) = {
        let app_state = state.lock().map_err(|e| e.to_string())?;
        app_state
            .jobs_cache
            .as_ref()
            .filter(|cache| cache.signature == signature)
            .map(|cache| cache.entries.clone())
    } {
        let mut cached = entries;
        cached.truncate(max_items);
        return Ok(cached);
    }
    let paths = paths_by_job.into_values().collect::<Vec<_>>();
    let mut out = Vec::new();
    for (modified, _, path) in paths {
        let bytes = match std::fs::read(&path) {
            Ok(bytes) => bytes,
            Err(_) => continue,
        };
        let value: JsonValue = match serde_json::from_slice(&bytes) {
            Ok(value) => value,
            Err(_) => continue,
        };
        let history_hidden = value
            .get("history_hidden")
            .or_else(|| value.get("historyHidden"))
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let raw_kind = value
            .get("kind")
            .and_then(|v| v.as_str())
            .unwrap_or("alpha_strategy_from_csv");
        if history_hidden
            || matches!(raw_kind, "custom_compute_program_run" | "visual_program_run")
        {
            continue;
        }
        let fallback_id = path
            .file_stem()
            .and_then(|s| s.to_str())
            .unwrap_or("")
            .to_string();
        let job_id = value
            .get("job_id")
            .and_then(|v| v.as_str())
            .unwrap_or(&fallback_id)
            .to_string();
        let status = value
            .get("status")
            .and_then(|v| v.as_str())
            .unwrap_or("unknown")
            .to_string();
        let archived = value.get("archived").and_then(|v| v.as_bool()).unwrap_or(false);
        let deleted = value.get("deleted").and_then(|v| v.as_bool()).unwrap_or(false);
        let status = if archived || deleted {
            "archived".to_string()
        } else {
            status
        };
        let title = value
            .get("title")
            .and_then(|v| v.as_str())
            .map(str::to_string)
            .or_else(|| value.get("original_file_name").and_then(|v| v.as_str()).map(str::to_string));
        let kind = raw_kind.to_string();
        let file_path = value
            .get("file_path")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        let file_count = value
            .get("file_count")
            .and_then(|v| v.as_u64())
            .or_else(|| value.get("file_paths").and_then(|v| v.as_array()).map(|v| v.len() as u64));
        let pinned = value.get("pinned").and_then(|v| v.as_bool());
        let strategy_hash = value
            .get("strategy_hash")
            .and_then(|v| v.as_str())
            .map(str::to_string);
        let bars = value.get("bars").and_then(|v| v.as_u64());
        let agents = value.get("agents").cloned();
        let context_accounting = value
            .get("context_accounting")
            .cloned()
            .or_else(|| value.get("contextAccounting").cloned());
        let performance = forge_job_performance(&value);
        let last_modified_ms = modified
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_millis() as u64;
        let unified_job = forge_job_runtime::ForgeUnifiedJob::from_manifest(
            &job_id,
            &kind,
            &status,
            &value,
            last_modified_ms,
        );
        out.push(ForgeJobEntry {
            job: unified_job,
            job_id,
            title,
            status,
            kind,
            file_path,
            file_count,
            pinned,
            strategy_hash,
            bars,
            agents,
            context_accounting,
            performance,
            last_modified_ms,
        });
    }
    out.sort_by(|a, b| {
        b.pinned
            .unwrap_or(false)
            .cmp(&a.pinned.unwrap_or(false))
            .then_with(|| b.last_modified_ms.cmp(&a.last_modified_ms))
    });
    if let Ok(mut app_state) = state.lock() {
        app_state.jobs_cache = Some(ForgeJobsCache {
            signature,
            entries: out.clone(),
        });
    }
    let mut limited = out;
    limited.truncate(max_items);
    Ok(limited)
}

#[tauri::command]
async fn forge_job_runtime_snapshot(
    limit: Option<usize>,
    state: tauri::State<'_, Mutex<ForgeAppState>>,
) -> Result<forge_job_runtime::ForgeJobLedgerSnapshot, String> {
    let store_path = {
        let app_state = state.lock().map_err(|e| e.to_string())?;
        app_state.store_path.clone()
    };
    forge_job_runtime::recover_job_ledger(&store_path, limit.unwrap_or(80).clamp(1, 500))
}

#[derive(Debug, Clone, Default, Deserialize)]
#[serde(rename_all = "camelCase")]
struct ForgeFbcRuntimeSnapshotRequest {
    backend: Option<String>,
    write_artifacts: Option<bool>,
    record_kernel: Option<bool>,
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
struct ForgeFbcRuntimeSnapshot {
    kind: String,
    registry_hash: String,
    tool_registry_hash: String,
    graph_hash: String,
    section_count: usize,
    sensitive_command_count: usize,
    tool_cell_registry_count: usize,
    cell_count: usize,
    ok_count: usize,
    denied_count: usize,
    ledger_root_hash: String,
    manifest_path: String,
    output_dir: String,
    job_id: String,
    job_event_id: String,
    projection: JsonValue,
}

#[tauri::command]
fn forge_fbc_runtime_snapshot(
    request: Option<ForgeFbcRuntimeSnapshotRequest>,
    state: tauri::State<'_, Mutex<ForgeAppState>>,
    kernel: tauri::State<'_, Mutex<forge_kernel::ForgeKernel>>,
) -> Result<ForgeFbcRuntimeSnapshot, String> {
    let request = request.unwrap_or_default();
    let store_path = {
        let app_state = state.lock().map_err(|e| e.to_string())?;
        app_state.store_path.clone()
    };
    let ownership_path = forge_workspace_dir()
        .join("examples")
        .join("forge_tauri_ui")
        .join("ui")
        .join("SECTION_OWNERSHIP.json");
    let ownership_json = std::fs::read_to_string(&ownership_path)
        .map_err(|e| format!("read SECTION_OWNERSHIP '{}': {e}", ownership_path.display()))?;
    let registry = parse_app_section_registry_v0(&ownership_json)
        .map_err(|e| format!("parse app FBC registry: {e:?}"))?;
    let tool_registry_path = forge_workspace_dir()
        .join("examples")
        .join("forge_tauri_ui")
        .join("source-registry")
        .join("real-estate-tool-cells.json");
    let tool_registry_json = std::fs::read_to_string(&tool_registry_path)
        .map_err(|e| format!("read real-estate tool cells '{}': {e}", tool_registry_path.display()))?;
    let tool_registry = parse_tool_cell_registry_v0(&tool_registry_json)
        .map_err(|e| format!("parse real-estate tool cell registry: {e:?}"))?;
    let tool_graph_path = store_path
        .join("real-estate-harvester")
        .join("data")
        .join("living_dataflow_graph.jsonl");
    let tool_graph_jsonl = if tool_graph_path.exists() {
        std::fs::read(&tool_graph_path)
            .map_err(|e| format!("read real-estate living graph '{}': {e}", tool_graph_path.display()))?
    } else {
        Vec::new()
    };
    let mut config = ForgeVmConfig::default();
    if let Some(backend) = request.backend.as_deref().map(str::trim).filter(|v| !v.is_empty()) {
        config.backend = backend.to_string();
    } else {
        config.backend = "auto".to_string();
    }
    let batch = execute_tool_cell_batch_groups(
        &[
            (&registry.cells, &registry.graph_jsonl),
            (&tool_registry.cells, &tool_graph_jsonl),
        ],
        &config,
    );
    let output_dir = store_path.join("fbc").join("app");
    let manifest_path = output_dir.join("app_fbc_registry_batch.json");
    if request.write_artifacts.unwrap_or(true) {
        std::fs::create_dir_all(&output_dir)
            .map_err(|e| format!("create FBC app output dir '{}': {e}", output_dir.display()))?;
        for record in &batch.records {
            let safe_name = safe_fbc_artifact_name(&record.command);
            let artifact = tool_cell_output_artifact_json(
                record,
                &batch.graph_hash,
                &registry.registry_hash,
                &batch.ledger_root_hash,
            );
            let path = output_dir.join(format!("{safe_name}.json"));
            std::fs::write(&path, format!("{artifact}\n"))
                .map_err(|e| format!("write FBC artifact '{}': {e}", path.display()))?;
        }
        std::fs::write(&manifest_path, format!("{}\n", batch.projection_json))
            .map_err(|e| format!("write FBC manifest '{}': {e}", manifest_path.display()))?;
    }
    let projection = serde_json::from_str::<JsonValue>(&batch.projection_json)
        .unwrap_or_else(|_| json!({ "kind": "forge_fbc_projection_parse_error", "raw": batch.projection_json }));
    let now_ms = now_epoch_ms() as u64;
    let job_id = format!("fbc-app-{now_ms}");
    let job = forge_job_runtime::ForgeUnifiedJob::new(
        job_id.clone(),
        "forge_fbc_app_runtime",
        json!({
            "registryHash": registry.registry_hash,
            "toolRegistryHash": tool_registry.registry_hash,
            "graphHash": batch.graph_hash,
            "sectionCount": registry.section_count,
            "sensitiveCommandCount": registry.sensitive_command_count,
            "toolCellRegistryCount": tool_registry.cells.len(),
            "cellCount": batch.tool_count,
            "okCount": batch.ok_count,
            "deniedCount": batch.denied_count,
            "ledgerRootHash": batch.ledger_root_hash,
            "manifestPath": manifest_path.display().to_string(),
            "rawInputReturned": false,
            "capabilityOnly": true,
        }),
        if batch.denied_count == 0 { "completed" } else { "denied" },
        forge_job_runtime::ForgeJobCost {
            estimate_units: batch.tool_count as u64,
            actual_units: batch.records.len() as u64,
            token_estimate: 0,
            budget_class: "light".to_string(),
        },
        forge_job_runtime::ForgeJobRetry::default(),
        forge_job_runtime::ForgeJobProof {
            hash: batch.ledger_root_hash.clone(),
            artifact_path: manifest_path.display().to_string(),
            source_hash: format!("{}:{}", registry.registry_hash, tool_registry.registry_hash),
        },
    );
    let event = forge_job_runtime::append_job_ledger_event(
        &store_path,
        "fbc.app.runtime.snapshot",
        now_ms,
        &job,
    )?;
    let snapshot = ForgeFbcRuntimeSnapshot {
        kind: "forge_fbc_app_runtime_snapshot_v0".to_string(),
        registry_hash: registry.registry_hash,
        tool_registry_hash: tool_registry.registry_hash,
        graph_hash: batch.graph_hash,
        section_count: registry.section_count,
        sensitive_command_count: registry.sensitive_command_count,
        tool_cell_registry_count: tool_registry.cells.len(),
        cell_count: batch.tool_count,
        ok_count: batch.ok_count,
        denied_count: batch.denied_count,
        ledger_root_hash: batch.ledger_root_hash,
        manifest_path: manifest_path.display().to_string(),
        output_dir: output_dir.display().to_string(),
        job_id,
        job_event_id: event.event_id,
        projection,
    };
    if request.record_kernel.unwrap_or(true) {
        let value = serde_json::to_value(&snapshot)
            .map_err(|e| format!("encode FBC runtime snapshot for kernel: {e}"))?;
        forge_kernel::record_fbc_runtime_snapshot(&kernel, value);
    }
    Ok(snapshot)
}

fn safe_fbc_artifact_name(command: &str) -> String {
    let mut out = command
        .trim_matches('/')
        .trim_end_matches('_')
        .chars()
        .map(|ch| if ch.is_ascii_alphanumeric() || ch == '-' || ch == '_' { ch } else { '_' })
        .collect::<String>();
    if out.is_empty() {
        out = "fbc_artifact".to_string();
    }
    out
}

