fn forge_fbc_guard_sensitive_action(
    kernel: &Mutex<forge_kernel::ForgeKernel>,
    store_path: Option<&Path>,
    action: &str,
    payload: JsonValue,
) -> Result<JsonValue, String> {
    let proof = forge_fbc_host::execute_sensitive_guard(store_path, action, &payload)?.proof;
    forge_kernel::record_preverified_fbc_guard(kernel, proof.clone());
    Ok(proof)
}

fn summarize_forge_program_manifest(value: &JsonValue, path: &Path, modified: SystemTime) -> JsonValue {
    let canonical = value.get("canonical").unwrap_or(&JsonValue::Null);
    let metrics = canonical
        .get("metrics")
        .and_then(|v| v.as_array())
        .or_else(|| value.get("metrics").and_then(|v| v.as_array()));
    let metric_count = metrics.map(|v| v.len()).unwrap_or(0);
    let metric_tags: Vec<String> = metrics
        .map(|items| {
            items
                .iter()
                .take(24)
                .filter_map(|metric| {
                    metric
                        .get("tag")
                        .or_else(|| metric.get("id"))
                        .or_else(|| metric.get("op"))
                        .and_then(|v| v.as_str())
                        .map(str::to_string)
                })
                .collect()
        })
        .unwrap_or_default();
    let last_modified_ms = modified
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis() as u64;
    json!({
        "programId": value.get("program_id").cloned().unwrap_or(JsonValue::Null),
        "programHash": value.get("program_hash").cloned().unwrap_or_else(|| {
            path.file_stem()
                .and_then(|s| s.to_str())
                .map(|s| json!(s))
                .unwrap_or(JsonValue::Null)
        }),
        "title": canonical.get("title").or_else(|| value.get("title")).cloned().unwrap_or(JsonValue::Null),
        "domain": canonical.get("domain").or_else(|| value.get("domain")).cloned().unwrap_or(JsonValue::Null),
        "intent": canonical.get("intent").or_else(|| value.get("intent")).cloned().unwrap_or(JsonValue::Null),
        "goal": canonical.get("goal").or_else(|| value.get("goal")).cloned().unwrap_or(JsonValue::Null),
        "template": canonical.get("template").or_else(|| value.get("template")).cloned().unwrap_or(JsonValue::Null),
        "kind": value.get("kind").cloned().unwrap_or_else(|| json!("forge_compute_program")),
        "views": canonical.get("views").or_else(|| value.get("views")).cloned().unwrap_or_else(|| json!([])),
        "outputContract": canonical.get("output_contract").or_else(|| value.get("output_contract")).cloned().unwrap_or(JsonValue::Null),
        "status": value.get("status").cloned().unwrap_or_else(|| json!("ready")),
        "metricCount": metric_count,
        "metricTags": metric_tags,
        "executionReadiness": value.get("execution_readiness").cloned().unwrap_or(JsonValue::Null),
        "createdMs": value.get("created_ms").cloned().unwrap_or(JsonValue::Null),
        "updatedMs": value.get("updated_ms").cloned().unwrap_or(JsonValue::Null),
        "lastModifiedMs": last_modified_ms,
        "contentAddressed": true,
        "sourceContentIncluded": false,
        "rawInputReturned": false
    })
}

fn remove_legacy_mars_lens_program(store_path: &Path) {
    let manifest_path = store_path.join("programs").join("mars-globe-lens-v1.json");
    let Ok(bytes) = std::fs::read(&manifest_path) else {
        return;
    };
    let Ok(value) = serde_json::from_slice::<JsonValue>(&bytes) else {
        return;
    };
    let is_legacy_builtin = value
        .get("program_hash")
        .and_then(JsonValue::as_str)
        .map(|hash| hash == "mars-globe-lens-v1")
        .unwrap_or(false);
    if is_legacy_builtin {
        let _ = std::fs::remove_file(manifest_path);
    }
}

fn ensure_builtin_mars_geonodes(store_path: &Path) -> Result<(), String> {
    forge_agent_tools::ensure_builtin_mars_geonodes(store_path)
}

fn forge_agent_binary_path() -> Result<PathBuf, String> {
    let current = std::env::current_exe().map_err(|e| format!("locate current executable: {e}"))?;
    let binary_name = if cfg!(windows) { "FORGE_AGENT.exe" } else { "FORGE_AGENT" };
    Ok(current.with_file_name(binary_name))
}

fn write_actcode_message<W: Write>(writer: &mut W, value: &JsonValue) -> Result<(), String> {
    let body = serde_json::to_vec(value).map_err(|e| format!("encode ActCode message: {e}"))?;
    write!(writer, "Content-Length: {}\r\n\r\n", body.len())
        .map_err(|e| format!("write ActCode header: {e}"))?;
    writer
        .write_all(&body)
        .map_err(|e| format!("write ActCode body: {e}"))?;
    writer.flush().map_err(|e| format!("flush ActCode stdin: {e}"))
}

fn read_actcode_message<R: BufRead>(reader: &mut R) -> Result<Option<JsonValue>, String> {
    let mut content_length = None;
    loop {
        let mut line = String::new();
        let read = reader
            .read_line(&mut line)
            .map_err(|e| format!("read ActCode header: {e}"))?;
        if read == 0 {
            return Ok(None);
        }
        let trimmed = line.trim_end_matches(['\r', '\n']);
        if trimmed.is_empty() {
            break;
        }
        if let Some((name, value)) = trimmed.split_once(':') {
            if name.eq_ignore_ascii_case("content-length") {
                content_length = Some(
                    value
                        .trim()
                        .parse::<usize>()
                        .map_err(|e| format!("parse ActCode content-length: {e}"))?,
                );
            }
        }
    }
    let len = content_length.ok_or_else(|| "ActCode response missing Content-Length".to_string())?;
    let mut body = vec![0u8; len];
    reader
        .read_exact(&mut body)
        .map_err(|e| format!("read ActCode body: {e}"))?;
    serde_json::from_slice(&body)
        .map(Some)
        .map_err(|e| format!("decode ActCode body: {e}"))
}

fn call_forge_agent_tool(store_path: PathBuf, tool: &str, args: JsonValue) -> Result<JsonValue, String> {
    let actcode_path = forge_agent_binary_path()?;
    if !actcode_path.exists() {
        return Err(format!(
            "Forge ActCode binary not found at '{}'. Build it with cargo build --bin FORGE_AGENT.",
            actcode_path.display()
        ));
    }
    let mut child = Command::new(&actcode_path)
        .env("FORGE_STORE_DIR", &store_path)
        .env("FORGE_AGENT_MODEL", "forge-ui")
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|e| format!("start Forge ActCode '{}': {e}", actcode_path.display()))?;

    {
        let stdin = child
            .stdin
            .as_mut()
            .ok_or_else(|| "Forge ActCode stdin unavailable".to_string())?;
        write_actcode_message(stdin, &json!({
            "jsonrpc": "2.0",
            "id": 1,
            "method": "initialize",
            "params": {
                "protocolVersion": "2024-11-05",
                "capabilities": {},
                "clientInfo": {
                    "name": "Forge UI",
                    "version": env!("CARGO_PKG_VERSION")
                }
            }
        }))?;
        write_actcode_message(stdin, &json!({
            "jsonrpc": "2.0",
            "method": "notifications/initialized",
            "params": {}
        }))?;
        write_actcode_message(stdin, &json!({
            "jsonrpc": "2.0",
            "id": 2,
            "method": "tools/call",
            "params": {
                "name": tool,
                "arguments": args
            }
        }))?;
    }
    drop(child.stdin.take());

    let stdout = child
        .stdout
        .take()
        .ok_or_else(|| "Forge ActCode stdout unavailable".to_string())?;
    let mut reader = BufReader::new(stdout);
    let mut tool_response = None;
    while let Some(message) = read_actcode_message(&mut reader)? {
        if message.get("id").and_then(JsonValue::as_i64) == Some(2) {
            tool_response = Some(message);
            break;
        }
    }
    let output = child
        .wait_with_output()
        .map_err(|e| format!("wait Forge ActCode: {e}"))?;
    let message = tool_response.ok_or_else(|| {
        let stderr = String::from_utf8_lossy(&output.stderr).trim().to_string();
        if stderr.is_empty() {
            "Forge ActCode did not return a tool response".to_string()
        } else {
            format!("Forge ActCode did not return a tool response: {stderr}")
        }
    })?;
    if let Some(error) = message.get("error") {
        return Err(format!("Forge ActCode tool error: {error}"));
    }
    let result = message
        .get("result")
        .cloned()
        .ok_or_else(|| "Forge ActCode response missing result".to_string())?;
    if let Some(text) = result
        .get("content")
        .and_then(JsonValue::as_array)
        .and_then(|items| items.first())
        .and_then(|item| item.get("text"))
        .and_then(JsonValue::as_str)
    {
        return match serde_json::from_str(text) {
            Ok(value) => Ok(value),
            Err(_) => Ok(json!({ "text": text })),
        };
    }
    Ok(result)
}

fn forge_program_run_cached(store_path: PathBuf, args: JsonValue) -> Result<JsonValue, String> {
    forge_program_run_cached_with(store_path, args, call_forge_agent_tool)
}

#[tauri::command]
async fn run_forge_program(
    request: ForgeProgramRunRequest,
    state: tauri::State<'_, Mutex<ForgeAppState>>,
) -> Result<JsonValue, String> {
    let store_path = {
        let app_state = state.lock().map_err(|e| e.to_string())?;
        app_state.store_path.clone()
    };
    let mut args = json!({
        "inputs": request.inputs.into_iter().map(|input| json!({
            "path": input.path,
            "role": input.role.unwrap_or_else(|| "data".to_string())
        })).collect::<Vec<_>>()
    });
    if let JsonValue::Object(ref mut obj) = args {
        if let Some(program_hash) = request.program_hash {
            obj.insert("program_hash".to_string(), json!(program_hash));
        }
        if let Some(program) = request.program {
            obj.insert("program".to_string(), json!(program));
        }
        if let Some(title) = request.title {
            obj.insert("title".to_string(), json!(title));
        }
        if let Some(dry_run) = request.dry_run {
            obj.insert("dry_run".to_string(), json!(dry_run));
        }
        if let Some(plan_only) = request.plan_only {
            obj.insert("plan_only".to_string(), json!(plan_only));
        }
    }
    tauri::async_runtime::spawn_blocking(move || forge_program_run_cached(store_path, args))
        .await
        .map_err(|e| format!("join Forge ActCode runner: {e}"))?
}

#[tauri::command]
async fn create_forge_program(
    request: ForgeProgramCreateRequest,
    state: tauri::State<'_, Mutex<ForgeAppState>>,
) -> Result<JsonValue, String> {
    let store_path = {
        let app_state = state.lock().map_err(|e| e.to_string())?;
        app_state.store_path.clone()
    };
    let mut args = json!({
        "title": request.title,
        "goal": request.goal,
        "spec_text": request.spec_text,
        "metrics": [],
        "source_schema": {
            "source_content_included": false
        },
        "constraints": {
            "created_from": "forge_ui",
            "source_content_policy": "hash inputs; do not return raw content"
        },
        "output_contract": {
            "returns": ["metrics.json", "proof.json", "job manifest", "hashes", "bounded logs"]
        }
    });
    if let JsonValue::Object(ref mut obj) = args {
        if let Some(domain) = request.domain.filter(|v| !v.trim().is_empty()) {
            obj.insert("domain".to_string(), json!(domain));
        }
        if let Some(intent) = request.intent.filter(|v| !v.trim().is_empty()) {
            obj.insert("intent".to_string(), json!(intent));
        }
        if let Some(template) = request.template.filter(|v| !v.trim().is_empty()) {
            obj.insert("template".to_string(), json!(template));
        }
        if let Some(program_kind) = request.program_kind.filter(|v| !v.trim().is_empty()) {
            obj.insert("program_kind".to_string(), json!(program_kind));
        }
    }
    tauri::async_runtime::spawn_blocking(move || call_forge_agent_tool(store_path, "create", args))
        .await
        .map_err(|e| format!("join Forge ActCode create: {e}"))?
}

#[tauri::command]
async fn list_forge_capability_templates(
    state: tauri::State<'_, Mutex<ForgeAppState>>,
) -> Result<Vec<JsonValue>, String> {
    let store_path = {
        let app_state = state.lock().map_err(|e| e.to_string())?;
        app_state.store_path.clone()
    };
    tauri::async_runtime::spawn_blocking(move || {
        let domains = [
            "finance",
            "timeseries",
            "documents",
            "biology",
            "code",
            "security",
            "chemistry",
            "medicine",
            "engineering",
            "aerospace",
            "simulation",
            "math",
            "energy",
            "manufacturing",
            "geospatial",
            "audio",
            "images",
            "networks",
            "generic",
        ];
        let mut seen = HashSet::new();
        let mut out = universal_forge_capability_templates();
        for template in &out {
            if let Some(key) = template.get("template").and_then(JsonValue::as_str) {
                seen.insert(key.to_string());
            }
        }
        for domain in domains {
            let response = call_forge_agent_tool(
                store_path.clone(),
                "capabilities",
                json!({ "domain": domain, "detailed": true }),
            )?;
            let templates = response
                .pointer("/data/template_registry/templates")
                .or_else(|| response.pointer("/template_registry/templates"))
                .and_then(JsonValue::as_array)
                .cloned()
                .unwrap_or_default();
            for template in templates {
                let key = template
                    .get("template")
                    .and_then(JsonValue::as_str)
                    .unwrap_or("")
                    .to_string();
                if key.is_empty() || !seen.insert(key) {
                    continue;
                }
                out.push(template);
            }
        }
        Ok(out)
    })
    .await
    .map_err(|e| format!("join Forge ActCode capabilities: {e}"))?
}

#[tauri::command]
async fn list_forge_programs(
    limit: Option<usize>,
    state: tauri::State<'_, Mutex<ForgeAppState>>,
) -> Result<Vec<JsonValue>, String> {
    let programs_dir = forge_programs_dir_from_state(&state)?;
    if let Some(store_path) = programs_dir.parent() {
        remove_legacy_mars_lens_program(store_path);
        ensure_builtin_mars_geonodes(store_path)?;
    }
    let entries = match std::fs::read_dir(&programs_dir) {
        Ok(entries) => entries,
        Err(err) if err.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
        Err(err) => return Err(format!("read Forge programs dir: {err}")),
    };
    let mut paths = Vec::new();
    for entry in entries.flatten() {
        let path = entry.path();
        if path.extension().and_then(|s| s.to_str()) != Some("json") {
            continue;
        }
        let modified = entry
            .metadata()
            .and_then(|m| m.modified())
            .unwrap_or(SystemTime::UNIX_EPOCH);
        paths.push((modified, path));
    }
    paths.sort_by(|a, b| b.0.cmp(&a.0));
    let max_items = limit.unwrap_or(100).clamp(1, 500);
    let mut out = Vec::new();
    for (modified, path) in paths {
        let bytes = match std::fs::read(&path) {
            Ok(bytes) => bytes,
            Err(_) => continue,
        };
        let value: JsonValue = match serde_json::from_slice(&bytes) {
            Ok(value) => value,
            Err(_) => continue,
        };
        out.push(summarize_forge_program_manifest(&value, &path, modified));
        if out.len() >= max_items {
            break;
        }
    }
    Ok(out)
}

