#[tauri::command]
async fn read_forge_job_log(
    job_id: String,
    state: tauri::State<'_, Mutex<ForgeAppState>>,
) -> Result<String, String> {
    if !safe_forge_job_id(&job_id) {
        return Err("invalid Forge job id".to_string());
    }
    let jobs_dir = forge_jobs_dir_from_state(&state)?;
    let all_job_dirs = forge_job_mirror_dirs(&jobs_dir);
    read_forge_job_log_from_dirs(&job_id, &all_job_dirs)
}

#[tauri::command]
async fn read_forge_job_log_tail(
    job_id: String,
    cursor: Option<u64>,
    max_bytes: Option<u64>,
    state: tauri::State<'_, Mutex<ForgeAppState>>,
) -> Result<JsonValue, String> {
    if !safe_forge_job_id(&job_id) {
        return Err("invalid Forge job id".to_string());
    }
    let jobs_dir = forge_jobs_dir_from_state(&state)?;
    let all_job_dirs = forge_job_mirror_dirs(&jobs_dir);
    read_forge_job_log_tail_from_dirs(
        &job_id,
        &all_job_dirs,
        cursor.unwrap_or(0),
        max_bytes.unwrap_or(65_536),
    )
}

#[tauri::command]
async fn read_forge_job_manifest(
    job_id: String,
    state: tauri::State<'_, Mutex<ForgeAppState>>,
) -> Result<JsonValue, String> {
    if !safe_forge_job_id(&job_id) {
        return Err("invalid Forge job id".to_string());
    }
    let jobs_dir = forge_jobs_dir_from_state(&state)?;
    let all_job_dirs = forge_job_mirror_dirs(&jobs_dir);
    let (manifest_path, manifest_bytes) = read_forge_job_manifest_from_dirs(&job_id, &all_job_dirs)?;
    let manifest_dir = manifest_path
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| jobs_dir.clone());
    let mut manifest: JsonValue = serde_json::from_slice(&manifest_bytes)
        .map_err(|e| format!("decode Forge job manifest: {e}"))?;
    if let JsonValue::Object(ref mut obj) = manifest {
        obj.insert("manifest_path".to_string(), json!(manifest_path.display().to_string()));
        obj.insert("manifest_bytes".to_string(), json!(manifest_bytes.len()));
        let log_path = manifest_dir.join(format!("{job_id}.log"));
        obj.insert("log_path".to_string(), json!(log_path.display().to_string()));
        obj.insert(
            "log_bytes".to_string(),
            json!(std::fs::metadata(&log_path).map(|m| m.len()).unwrap_or(0)),
        );
    }
    Ok(manifest)
}

fn forge_tail_lines(text: &str, limit: usize) -> Vec<String> {
    let mut lines: Vec<String> = text
        .lines()
        .map(|line| line.trim_end().to_string())
        .filter(|line| !line.trim().is_empty())
        .collect();
    if lines.len() > limit {
        lines.drain(0..lines.len() - limit);
    }
    lines
}

fn compact_manifest_for_canvas(manifest: &JsonValue) -> JsonValue {
    let file_paths = manifest
        .get("file_paths")
        .or_else(|| manifest.get("filePaths"))
        .cloned()
        .unwrap_or_else(|| {
            manifest
                .get("file_path")
                .or_else(|| manifest.get("filePath"))
                .and_then(JsonValue::as_str)
                .map(|path| json!([path]))
                .unwrap_or_else(|| json!([]))
        });
    json!({
        "job_id": manifest.get("job_id").or_else(|| manifest.get("jobId")).cloned().unwrap_or(JsonValue::Null),
        "title": manifest.get("title").cloned().unwrap_or(JsonValue::Null),
        "status": manifest.get("status").cloned().unwrap_or(JsonValue::Null),
        "kind": manifest.get("kind").cloned().unwrap_or(JsonValue::Null),
        "file_count": manifest.get("file_count").or_else(|| manifest.get("fileCount")).cloned().unwrap_or(JsonValue::Null),
        "file_paths": file_paths,
        "file_summaries": manifest.get("file_summaries").or_else(|| manifest.get("fileSummaries")).cloned().unwrap_or_else(|| json!([])),
        "raw_content_included": false,
        "file_hash": manifest.get("file_hash").or_else(|| manifest.get("fileHash")).cloned().unwrap_or(JsonValue::Null),
        "strategy_hash": manifest.get("strategy_hash").or_else(|| manifest.get("strategyHash")).cloned().unwrap_or(JsonValue::Null),
        "program_hash": manifest.get("program_hash").or_else(|| manifest.get("programHash")).cloned().unwrap_or(JsonValue::Null),
        "bars": manifest.get("bars").cloned().unwrap_or(JsonValue::Null),
        "holdout": manifest.get("holdout").cloned().unwrap_or(JsonValue::Null),
    })
}

fn list_forge_programs_from_store(store_path: &Path, limit: usize) -> Result<Vec<JsonValue>, String> {
    remove_legacy_mars_lens_program(store_path);
    ensure_builtin_mars_geonodes(store_path)?;
    let programs_dir = store_path.join("programs");
    let entries = match std::fs::read_dir(&programs_dir) {
        Ok(entries) => entries,
        Err(err) if err.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
        Err(err) => return Err(format!("read Forge programs dir: {err}")),
    };
    let mut paths = Vec::new();
    for entry in entries.flatten() {
        let path = entry.path();
        if path.extension().and_then(|s| s.to_str()) != Some("json") {
            continue;
        }
        let modified = entry
            .metadata()
            .and_then(|m| m.modified())
            .unwrap_or(SystemTime::UNIX_EPOCH);
        paths.push((modified, path));
    }
    paths.sort_by(|a, b| b.0.cmp(&a.0));
    let max_items = limit.clamp(1, 500);
    let mut out = Vec::new();
    for (modified, path) in paths {
        let bytes = match std::fs::read(&path) {
            Ok(bytes) => bytes,
            Err(_) => continue,
        };
        let value: JsonValue = match serde_json::from_slice(&bytes) {
            Ok(value) => value,
            Err(_) => continue,
        };
        out.push(summarize_forge_program_manifest(&value, &path, modified));
        if out.len() >= max_items {
            break;
        }
    }
    Ok(out)
}

