fn semantic_cache_signature(text: &str) -> (String, Vec<String>) {
    const STOP_WORDS: &[&str] = &[
        "a", "ai", "au", "aux", "avec", "ce", "ces", "cest", "c'est", "dans", "de", "des",
        "du", "elle", "en", "est", "et", "il", "je", "j", "la", "le", "les", "me", "moi",
        "mon", "ma", "mes", "ne", "on", "ou", "oÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¹", "pas", "peux", "peut", "pour", "que",
        "qui", "quoi", "se", "sur", "ta", "te", "tes", "toi", "ton", "tu", "un", "une",
        "vous", "the", "a", "an", "and", "are", "can", "for", "how", "i", "in", "is",
        "it", "me", "of", "on", "or", "that", "to", "what", "you",
    ];
    let mut cleaned = String::with_capacity(text.len());
    for ch in text.to_lowercase().chars() {
        if ch.is_alphanumeric() {
            cleaned.push(ch);
        } else {
            cleaned.push(' ');
        }
    }
    let mut tokens = cleaned
        .split_whitespace()
        .filter(|token| token.len() >= 2 && !STOP_WORDS.contains(token))
        .take(64)
        .map(str::to_string)
        .collect::<Vec<_>>();
    tokens.sort();
    tokens.dedup();
    let normalized = tokens.join(" ");
    (normalized, tokens)
}

fn semantic_cache_similarity(left: &[String], right: &[String]) -> f64 {
    if left.is_empty() || right.is_empty() {
        return 0.0;
    }
    let mut i = 0usize;
    let mut j = 0usize;
    let mut intersection = 0usize;
    while i < left.len() && j < right.len() {
        match left[i].cmp(&right[j]) {
            std::cmp::Ordering::Equal => {
                intersection += 1;
                i += 1;
                j += 1;
            }
            std::cmp::Ordering::Less => i += 1,
            std::cmp::Ordering::Greater => j += 1,
        }
    }
    if intersection == 0 {
        return 0.0;
    }
    let union = left.len() + right.len() - intersection;
    let jaccard = intersection as f64 / union as f64;
    let containment = intersection as f64 / left.len().min(right.len()) as f64;
    let length_ratio = left.len().min(right.len()) as f64 / left.len().max(right.len()) as f64;
    (jaccard * 0.7 + containment * 0.3) * length_ratio.sqrt()
}

fn semantic_cache_is_cacheable(user_message: &str, assistant_message: &str) -> bool {
    let user_len = user_message.trim().chars().count();
    let assistant_len = assistant_message.trim().chars().count();
    (8..=700).contains(&user_len) && (2..=2_000).contains(&assistant_len)
}

/// Produce a chat assistant message that surfaces the real headless CLI
/// failure (Gemini / Claude) when one is captured, instead of the generic
/// "n'a pas pu répondre" fallback. The user can then see whether the CLI
/// failed because of an expired API key, exhausted quota, unavailable model,
/// missing OAuth refresh, etc.
///
/// The detail is sniffed for common Google AI / Anthropic error families and
/// translated to a French-language hint; the raw CLI output is always kept
/// underneath so the user has the ground truth.
fn compose_headless_cli_failure_message(
    generic: &str,
    detail: Option<&str>,
    provider_label: &str,
) -> String {
    let Some(raw_detail) = detail.map(str::trim).filter(|s| !s.is_empty()) else {
        return generic.to_string();
    };
    let hint = classify_headless_cli_failure(raw_detail, provider_label);
    let truncated = if raw_detail.len() > 1200 {
        let mut cut = 1200;
        while !raw_detail.is_char_boundary(cut) && cut > 0 {
            cut -= 1;
        }
        format!("{}…", &raw_detail[..cut])
    } else {
        raw_detail.to_string()
    };
    match hint {
        Some(hint) => format!("{generic}\n\n{hint}\n\nDétail CLI:\n{truncated}"),
        None => format!("{generic}\n\nDétail CLI:\n{truncated}"),
    }
}

/// Classify a headless CLI error string into a short French-language hint
/// pointing the user toward the most likely cause. Returns `None` when the
/// shape of the error doesn't match any known family — in that case the raw
/// detail is shown without an interpretation.
fn classify_headless_cli_failure(detail: &str, provider_label: &str) -> Option<String> {
    let lower = detail.to_ascii_lowercase();
    if lower.contains("resource_exhausted")
        || lower.contains("quota")
        || lower.contains("rate limit")
        || lower.contains("429")
    {
        return Some(format!(
            "Cause probable : quota {provider_label} épuisé. Attendez la fin du cycle de facturation ou augmentez le quota."
        ));
    }
    if lower.contains("permission_denied")
        || lower.contains("unauthenticated")
        || lower.contains("invalid api key")
        || lower.contains("api key not valid")
        || lower.contains("401")
        || lower.contains("403")
    {
        return Some(format!(
            "Cause probable : clé API / authentification {provider_label} invalide ou expirée. Régénérez la clé puis enregistrez-la depuis le terminal {provider_label} embarqué."
        ));
    }
    if lower.contains("invalid_argument")
        && (lower.contains("model") || lower.contains("modèle"))
        || lower.contains("model not found")
        || lower.contains("unsupported model")
    {
        return Some(format!(
            "Cause probable : modèle {provider_label} indisponible pour ce compte. Choisissez un autre modèle dans le menu LLM."
        ));
    }
    if lower.contains("timed out") || lower.contains("timeout") {
        return Some(format!(
            "Cause probable : la CLI {provider_label} a dépassé le délai imparti (180 s). Réessayez ou allégez la requête."
        ));
    }
    if lower.contains("network")
        || lower.contains("connection refused")
        || lower.contains("dns")
        || lower.contains("getaddrinfo")
    {
        return Some(
            "Cause probable : connectivité réseau coupée vers les serveurs Google / Anthropic.".to_string(),
        );
    }
    if lower.contains("oauth") || lower.contains("refresh token") || lower.contains("creds.json") {
        return Some(format!(
            "Cause probable : la session OAuth {provider_label} a expiré. Ouvrez le terminal {provider_label} embarqué et relancez la connexion."
        ));
    }
    None
}

fn sanitize_canvas_assistant_message(text: &str) -> String {
    let cleaned_lines: Vec<&str> = text
        .lines()
        .filter(|line| {
            let normalized = normalized_canvas_micro_text(line);
            !normalized.contains("dans ce tour precis")
                && !normalized.contains("dans ce tour")
                && !normalized.contains("sans executer d outils")
                && !normalized.contains("sans execution d outils")
                && !normalized.contains("je n ai rien lance")
                && !normalized.contains("aucun outil")
                && !normalized.contains("outil forge n est attache")
                && !normalized.contains("outils forge ne sont")
                && !normalized.contains("au tour suivant")
        })
        .collect();
    let cleaned = cleaned_lines.join("\n").trim().to_string();
    if cleaned.is_empty() {
        text.trim().to_string()
    } else {
        cleaned
    }
}

#[derive(Clone, Default)]
struct RealEstatePrivacyRedactionCounts {
    email: usize,
    phone: usize,
    iban: usize,
    nir: usize,
    address: usize,
}

impl RealEstatePrivacyRedactionCounts {
    fn total(&self) -> usize {
        self.email + self.phone + self.iban + self.nir + self.address
    }

    fn to_json(&self) -> JsonValue {
        json!({
            "email": self.email,
            "phone": self.phone,
            "iban": self.iban,
            "nir": self.nir,
            "address": self.address,
            "total": self.total()
        })
    }

    fn summary(&self) -> String {
        format!(
            "email={},phone={},iban={},nir={},address={},total={}",
            self.email,
            self.phone,
            self.iban,
            self.nir,
            self.address,
            self.total()
        )
    }
}

fn forge_real_estate_privacy_applies(message: &str) -> bool {
    let lower = message.to_lowercase();
    message.contains("FORGE_REAL_ESTATE_PRIVACY:")
        || message.contains("FORGE_REAL_ESTATE_PROGRAM_COMMAND:")
        || message.contains("FORGE_REAL_ESTATE_ONBOARDING:")
        || lower.contains("scope=agence_immo")
        || lower.contains("agence immo")
}

fn forge_canvas_message_forces_runtime_context(message: &str) -> bool {
    message.contains("FORGE_REAL_ESTATE_ONBOARDING:")
        || message.contains("FORGE_REAL_ESTATE_PROGRAM_COMMAND:")
        || message.contains("FORGE_REAL_ESTATE_MEMORY_CONTEXT:")
        || message.contains("FORGE_REAL_ESTATE_LLM_INTEL_CACHE:")
}

fn forge_privacy_hash(text: &str) -> String {
    let mut hash = 0xcbf29ce484222325u64;
    for byte in text.as_bytes() {
        hash ^= *byte as u64;
        hash = hash.wrapping_mul(0x100000001b3);
    }
    format!("{hash:016x}")
}

fn redact_real_estate_address_lines(
    text: &str,
    counts: &mut RealEstatePrivacyRedactionCounts,
) -> String {
    let keywords = [
        "adresse",
        "address",
        "rue",
        "avenue",
        "av.",
        "boulevard",
        "bd",
        "impasse",
        "chemin",
        "route",
        "allee",
        "place",
        "quai",
        "residence",
    ];
    let mut output = String::with_capacity(text.len());
    for part in text.split_inclusive('\n') {
        let newline = if part.ends_with("\r\n") {
            "\r\n"
        } else if part.ends_with('\n') {
            "\n"
        } else {
            ""
        };
        let line = if newline.is_empty() {
            part
        } else {
            &part[..part.len() - newline.len()]
        };
        let lower = line.to_lowercase();
        let trimmed = lower.trim_start();
        let looks_like_internal_route =
            trimmed.starts_with("route=") || trimmed.starts_with("data_context=");
        let should_redact = !looks_like_internal_route
            && line.chars().any(|ch| ch.is_ascii_digit())
            && keywords.iter().any(|keyword| lower.contains(keyword));
        if should_redact {
            counts.address += 1;
            if lower.trim_start().starts_with("adresse") || lower.trim_start().starts_with("address")
            {
                if let Some(idx) = line.find(':').or_else(|| line.find('=')).or_else(|| line.find('-'))
                {
                    output.push_str(&line[..=idx]);
                    output.push_str(" [ADRESSE_CLIENT_REDACTED]");
                } else {
                    output.push_str("[ADRESSE_CLIENT_REDACTED]");
                }
            } else {
                output.push_str("[ADRESSE_CLIENT_REDACTED]");
            }
        } else {
            output.push_str(line);
        }
        output.push_str(newline);
    }
    output
}

fn token_core_for_privacy(token: &str) -> String {
    token
        .trim_matches(|ch: char| {
            !(ch.is_ascii_alphanumeric() || matches!(ch, '@' | '.' | '+' | '-' | '_'))
        })
        .to_string()
}

fn looks_like_email_token(token: &str) -> bool {
    let Some((left, domain)) = token.split_once('@') else {
        return false;
    };
    !left.is_empty()
        && domain.contains('.')
        && domain
            .rsplit_once('.')
            .map(|(_, suffix)| suffix.len() >= 2 && suffix.chars().all(|ch| ch.is_ascii_alphabetic()))
            .unwrap_or(false)
}

fn looks_like_iban_token(token: &str) -> bool {
    let compact = token
        .chars()
        .filter(|ch| ch.is_ascii_alphanumeric())
        .collect::<String>()
        .to_ascii_uppercase();
    compact.starts_with("FR")
        && (16..=34).contains(&compact.len())
        && compact.chars().all(|ch| ch.is_ascii_alphanumeric())
}

fn redact_real_estate_tokens(
    text: &str,
    counts: &mut RealEstatePrivacyRedactionCounts,
) -> String {
    let mut output = String::with_capacity(text.len());
    let mut token = String::new();
    let flush_token = |token: &mut String,
                       output: &mut String,
                       counts: &mut RealEstatePrivacyRedactionCounts| {
        if token.is_empty() {
            return;
        }
        let core = token_core_for_privacy(token);
        if looks_like_email_token(&core) {
            counts.email += 1;
            output.push_str("[EMAIL_CLIENT_REDACTED]");
        } else if looks_like_iban_token(&core) {
            counts.iban += 1;
            output.push_str("[IBAN_CLIENT_REDACTED]");
        } else {
            output.push_str(token);
        }
        token.clear();
    };
    for ch in text.chars() {
        if ch.is_whitespace() {
            flush_token(&mut token, &mut output, counts);
            output.push(ch);
        } else {
            token.push(ch);
        }
    }
    flush_token(&mut token, &mut output, counts);
    output
}

fn redact_real_estate_digit_sequences(
    text: &str,
    counts: &mut RealEstatePrivacyRedactionCounts,
) -> String {
    let mut output = String::with_capacity(text.len());
    let mut cursor = 0usize;
    let mut iter = text.char_indices().peekable();
    while let Some((idx, ch)) = iter.next() {
        if !(ch.is_ascii_digit() || ch == '+') {
            continue;
        }
        let mut end = idx + ch.len_utf8();
        let mut digit_count = usize::from(ch.is_ascii_digit());
        while let Some(&(next_idx, next_ch)) = iter.peek() {
            if next_ch.is_ascii_digit()
                || matches!(next_ch, ' ' | '.' | '-' | '(' | ')' | '/')
            {
                iter.next();
                end = next_idx + next_ch.len_utf8();
                if next_ch.is_ascii_digit() {
                    digit_count += 1;
                }
            } else {
                break;
            }
        }
        if digit_count < 10 {
            continue;
        }
        let segment = &text[idx..end];
        let compact = segment.trim();
        let digits = segment
            .chars()
            .filter(|ch| ch.is_ascii_digit())
            .collect::<String>();
        let has_phone_separator = segment
            .chars()
            .any(|ch| matches!(ch, ' ' | '.' | '-' | '(' | ')'));
        let is_nir = (13..=15).contains(&digits.len())
            && (digits.starts_with('1') || digits.starts_with('2'));
        let is_phone = (10..=14).contains(&digits.len())
            && (compact.starts_with("+33")
                || compact.starts_with("0033")
                || digits.starts_with('0')
                || (digits.starts_with("33") && has_phone_separator));
        if is_nir || is_phone {
            output.push_str(&text[cursor..idx]);
            if is_nir {
                counts.nir += 1;
                output.push_str("[NIR_CLIENT_REDACTED]");
            } else {
                counts.phone += 1;
                output.push_str("[TELEPHONE_CLIENT_REDACTED]");
            }
            cursor = end;
        }
    }
    output.push_str(&text[cursor..]);
    output
}

fn redact_real_estate_client_text(text: &str) -> (String, RealEstatePrivacyRedactionCounts) {
    let mut counts = RealEstatePrivacyRedactionCounts::default();
    let address_safe = redact_real_estate_address_lines(text, &mut counts);
    let token_safe = redact_real_estate_tokens(&address_safe, &mut counts);
    let digit_safe = redact_real_estate_digit_sequences(&token_safe, &mut counts);
    (digit_safe, counts)
}

fn forge_real_estate_privacy_envelope(
    message: &str,
    counts: &RealEstatePrivacyRedactionCounts,
    original_hash: &str,
    sanitized_hash: &str,
) -> String {
    if message.contains("FORGE_REAL_ESTATE_PRIVACY_BACKEND_GUARD:") {
        return message.to_string();
    }
    [
        "FORGE_REAL_ESTATE_PRIVACY_BACKEND_GUARD:".to_string(),
        "mode=local_first_client_data_minimized".to_string(),
        "scope=agence_immo".to_string(),
        "assistant_role=assistant IA qui bosse pour l'agence immobiliere active".to_string(),
        "assistant_identity_rule=toujours parler et raisonner comme l'assistant IA de cette agence, meme pendant une reponse libre".to_string(),
        "raw_client_files=local_only".to_string(),
        "external_runtime_payload=redacted_before_dispatch".to_string(),
        format!("redactions={}", counts.summary()),
        format!("original_hash={original_hash}"),
        format!("sanitized_hash={sanitized_hash}"),
        "instruction=Never ask the user to paste raw client files or reveal personal identifiers; use Forge compact hashes, proofs, summaries and local memory refs.".to_string(),
        String::new(),
        message.to_string(),
    ]
    .join("\n")
}

