fn normalize_canvas_thread_key(session_key: &str) -> String {
    if session_key.trim().is_empty() {
        "forge-default".to_string()
    } else {
        session_key.trim().to_string()
    }
}

fn compact_canvas_thread_memory(state: &CodexThreadState) -> Option<String> {
    if state.memory.is_empty() {
        return None;
    }
    let body = state.memory.join("\n");
    let compact = format!(
        "thread_generation_precedente={}\nresume_session_complete_compacte:\n{}",
        state.generation, body
    );
    Some(compact_thread_memory_preserve_tail(
        &compact,
        CODEX_CANVAS_COMPACT_MEMORY_MAX_CHARS,
    ))
}

fn prepare_gemini_thread_memory(
    state: &tauri::State<'_, Mutex<ForgeAppState>>,
    session_key: &str,
) -> Result<(Option<String>, u32), String> {
    let key = normalize_canvas_thread_key(session_key);
    let mut app_state = state.lock().map_err(|e| e.to_string())?;
    let entry = app_state
        .gemini_threads
        .entry(key.clone())
        .or_insert_with(|| CodexThreadState {
            turns: 0,
            generation: 0,
            memory: Vec::new(),
        });
    if entry.turns >= CODEX_CANVAS_THREAD_MAX_TURNS {
        entry.generation = entry.generation.saturating_add(1);
        entry.turns = 0;
        compact_canvas_thread_state_memory(entry, true);
    }
    Ok((compact_canvas_thread_memory(entry), entry.generation))
}

fn record_gemini_thread_turn(
    state: &tauri::State<'_, Mutex<ForgeAppState>>,
    session_key: &str,
    user_message: &str,
    assistant_message: &str,
) {
    let key = normalize_canvas_thread_key(session_key);
    let Ok(mut app_state) = state.lock() else {
        return;
    };
    let entry = app_state
        .gemini_threads
        .entry(key.clone())
        .or_insert_with(|| CodexThreadState {
            turns: 0,
            generation: 0,
            memory: Vec::new(),
        });
    entry.turns = entry.turns.saturating_add(1);
    let user = truncate_for_thread_memory(user_message, CODEX_CANVAS_MEMORY_USER_MAX_CHARS);
    let assistant =
        truncate_for_thread_memory(assistant_message, CODEX_CANVAS_MEMORY_ASSISTANT_MAX_CHARS);
    if !user.is_empty() || !assistant.is_empty() {
        entry.memory.push(format!("U: {user}\nG: {assistant}"));
    }
    compact_canvas_thread_state_memory(entry, false);
}

