    fn invoke_handler_block(source: &str) -> &str {
        let start = source
            .find(".invoke_handler(tauri::generate_handler![")
            .expect("invoke handler start");
        let rest = &source[start..];
        let end = rest.find("])").expect("invoke handler end");
        &rest[..end]
    }

    fn tauri_command_function_snippet<'a>(source: &'a str, command: &str) -> &'a str {
        let sync_marker = format!("fn {command}");
        let async_marker = format!("async fn {command}");
        let command_attr = ["\n#[tauri", "::command]"].concat();
        let start = source
            .find(&async_marker)
            .or_else(|| source.find(&sync_marker))
            .unwrap_or_else(|| panic!("missing tauri command function for {command}"));
        let rest = &source[start..];
        let next = rest.find(&command_attr).unwrap_or(rest.len());
        &rest[..next]
    }

    #[test]
    fn sensitive_tauri_commands_have_guard_metadata_and_registered_handlers() {
        let source = main_rs_source();
        let invoke_block = invoke_handler_block(&source);
        let ownership_path = workspace_file("../ui/SECTION_OWNERSHIP.json");
        let ownership_json = fs::read_to_string(&ownership_path).expect("read SECTION_OWNERSHIP");
        let ownership_value: JsonValue = serde_json::from_str(&ownership_json).expect("parse SECTION_OWNERSHIP");
        let ownership_sensitive = ownership_value
            .get("sensitiveCommands")
            .and_then(JsonValue::as_array)
            .expect("sensitiveCommands array");
        let metadata = sensitive_tauri_command_guard_metadata();

        let mut by_command = std::collections::BTreeMap::new();
        for item in metadata {
            assert!(
                by_command.insert(item.command, item).is_none(),
                "duplicate sensitive metadata for {}",
                item.command
            );
            assert!(
                invoke_block.contains(&format!("{},", item.command)),
                "sensitive command {} missing from tauri invoke handler",
                item.command
            );
        }

        let expected_sensitive = [
            "webexplorer_native_present",
            "webexplorer_native_hide",
            "agency_earth_native_present",
            "agency_earth_native_hide",
            "agency_web_item_native_present",
            "agency_web_item_native_hide",
            "bloomberg_live_native_present",
            "bloomberg_live_native_hide",
            "list_forge_jobs",
            "read_forge_job_file",
            "read_forge_job_artifact_text",
            "publish_forge_job_to_actcode",
            "get_hardware_info",
            "open_url",
            "gmail_webview_action_surface",
            "google_oauth_start",
        ];
        for command in expected_sensitive {
            assert!(
                by_command.contains_key(command),
                "sensitive command {} lacks guard metadata",
                command
            );
        }

        for entry in ownership_sensitive {
            let command = entry
                .get("command")
                .and_then(JsonValue::as_str)
                .expect("ownership sensitive command");
            let owner = entry.get("owner").and_then(JsonValue::as_str).unwrap_or("");
            let requires_bridge = entry
                .get("requiresBridge")
                .and_then(JsonValue::as_bool)
                .unwrap_or(false);
            let allow_raw_fallback = entry
                .get("allowRawFallback")
                .and_then(JsonValue::as_bool)
                .unwrap_or(false);
            let boot_safe = entry
                .get("bootSafe")
                .and_then(JsonValue::as_bool)
                .unwrap_or(false);
            let meta = by_command
                .get(command)
                .unwrap_or_else(|| panic!("SECTION_OWNERSHIP sensitive command {} missing backend metadata", command));
            assert_eq!(meta.owner, owner, "owner drift for {}", command);
            assert_eq!(meta.allow_raw_fallback, allow_raw_fallback, "allowRawFallback drift for {}", command);
            assert_eq!(meta.boot_safe, boot_safe, "bootSafe drift for {}", command);
            if requires_bridge {
                assert!(
                    matches!(
                        meta.surface,
                        "native_present"
                            | "native_hide"
                            | "jobs_projection"
                            | "artifact_read"
                            | "artifact_publish"
                            | "hardware_probe"
                            | "network_source"
                    ),
                    "bridge-sensitive command {} should use a bridge-aware metadata surface",
                    command
                );
            }
        }

        for item in metadata.iter().filter(|item| item.requires_fbc_guard) {
            let snippet = tauri_command_function_snippet(&source, item.command);
            assert!(
                snippet.contains("forge_fbc_guard_sensitive_action("),
                "sensitive command {} requires FBC guard metadata but is not guarded in backend",
                item.command
            );
            assert!(
                snippet.contains(&format!("\"{}\"", item.command)),
                "sensitive command {} must bind its exact guard action name in backend",
                item.command
            );
        }
    }

    fn sample_alpha_bars(n: usize) -> Vec<trading::Bar> {
        let mut bars = Vec::with_capacity(n);
        let start_ms = 3 * 3_600_000_i64;
        for i in 0..n {
            let t = start_ms + i as i64 * 4 * 3_600_000_i64;
            let phase = i as f64 / 4.0;
            let drift = i as f64 * 0.0008;
            let base = 3.0 + 0.16 * phase.sin() + drift;
            let open = base;
            let close = base + 0.025 * (phase * 0.7).cos();
            let high = open.max(close) + 0.03 + 0.005 * phase.cos().abs();
            let low = open.min(close) - 0.03 - 0.005 * phase.sin().abs();
            let volume = 500.0 + (i % 17) as f64 * 23.0;
            bars.push(trading::Bar {
                time_ms: t,
                open,
                high,
                low,
                close,
                volume,
            });
        }
        bars
    }

    #[test]
    fn depth2_enumerator_produces_non_trivial_cse_collapse() {
        let examples: Vec<(i64, i64)> = (0..20).map(|i| (i, 1)).collect();
        let candidates = enumerate_synth_candidates_d2(&examples);
        assert!(
            candidates.len() > 100,
            "expected >100 depth-2 candidates, got {}",
            candidates.len()
        );

        let s = cse_classify_candidates_with_reps(&candidates);
        let (raw, classes, redundancy) = (s.raw, s.n_classes, s.redundancy_pct);
        assert_eq!(raw, candidates.len());
        eprintln!(
            "[depth2 enum] {raw} raw candidates -> {classes} CSE classes ({redundancy:.1}% redundancy)"
        );
        assert!(
            classes < raw,
            "CSE should collapse some equivalents (raw={raw}, classes={classes})"
        );
        assert!(
            redundancy > 20.0,
            "expected >20% CSE redundancy on depth-2 space, got {redundancy:.1}%"
        );
    }

    #[test]
    fn depth3_enumerator_extends_redundancy() {
        let examples: Vec<(i64, i64)> = (0..20).map(|i| (i, 1)).collect();
        let mut candidates = enumerate_synth_candidates_d2(&examples);
        let d2_count = candidates.len();
        candidates.extend(enumerate_synth_candidates_d3(&examples));
        let total = candidates.len();
        assert!(
            total > d2_count,
            "d3 enumerator should add candidates ({total} <= {d2_count})"
        );

        let cse = cse_classify_candidates_with_reps(&candidates);
        assert_eq!(cse.raw, total);
        assert_eq!(cse.live_reps.len() + cse.static_count, cse.n_classes);
        eprintln!(
            "[d2+d3 enum] {} raw ({d2_count} d2 + {} d3) -> {} CSE classes ({:.1}% redundancy, {} provably-constant)",
            cse.raw,
            cse.raw - d2_count,
            cse.n_classes,
            cse.redundancy_pct,
            cse.static_count
        );
        assert!(
            cse.redundancy_pct > 30.0,
            "expected >30% CSE redundancy on depth-2+3 space, got {:.1}%",
            cse.redundancy_pct
        );
        assert!(
            cse.static_count > 0,
            "expected some provably-constant programs, got {}",
            cse.static_count
        );
    }

    #[test]
    fn trace_classifier_collapses_data_equivalent_beyond_cse() {
        let examples: Vec<(i64, i64)> = (0..20).map(|i| (i, 1)).collect();
        let mut candidates = enumerate_synth_candidates_d2(&examples);
        candidates.extend(enumerate_synth_candidates_d3(&examples));
        let cse = cse_classify_candidates_with_reps(&candidates);

        let inputs: Vec<i64> = (0..16).collect();
        let trace = trace_classify_reps(&cse.live_reps, &inputs, 16);
        eprintln!(
            "[trace classify] {} CSE reps -> {} trace classes | {} tautological | {} identity | top class: {} members | static (provably const): {}",
            cse.n_classes,
            trace.n_trace_classes,
            trace.tautological,
            trace.identity,
            trace.top_class_size,
            cse.static_count
        );
        assert!(
            trace.n_trace_classes <= cse.n_classes,
            "trace classes ({}) should be <= CSE classes ({})",
            trace.n_trace_classes,
            cse.n_classes
        );
        assert!(
            trace.n_trace_classes < cse.n_classes,
            "expected trace clustering to collapse beyond CSE (got {} == {})",
            trace.n_trace_classes,
            cse.n_classes
        );
        assert!(
            trace.tautological > 0,
            "expected some tautological candidates, got {}",
            trace.tautological
        );
    }

    #[test]
    fn subtree_mining_reveals_mass_sublevel_redundancy() {
        let examples: Vec<(i64, i64)> = (0..20).map(|i| (i, 1)).collect();
        let mut candidates = enumerate_synth_candidates_d2(&examples);
        candidates.extend(enumerate_synth_candidates_d3(&examples));

        let sub = analyze_subtree_redundancy(&candidates);
        assert!(
            sub.total_subtrees > candidates.len(),
            "expected more sub-trees than candidates (each d3 yields 2)"
        );
        assert!(
            sub.unique_subtrees < sub.total_subtrees,
            "expected dedup at sub-tree level"
        );
        eprintln!(
            "[sub-tree mining] {} candidates -> {} sub-evaluations -> {} unique sub-trees ({:.1}% redundancy)",
            candidates.len(),
            sub.total_subtrees,
            sub.unique_subtrees,
            sub.redundancy_pct
        );
        // Mass redundancy: every depth-3 candidate's INNER sub-tree is
        // structurally a depth-2 form, so all 21k inner sub-trees collapse
        // into the same ~200 depth-2 CSE classes. Expect >80%.
        assert!(
            sub.redundancy_pct > 80.0,
            "expected >80% sub-tree redundancy, got {:.1}%",
            sub.redundancy_pct
        );
    }

    #[test]
    fn subwindow_redundancy_reports_real_savings_on_natgas_size() {
        // NATGAS H4 is ~25,381 bars over 16 years.
        let stats = analyze_subwindow_redundancy(25_381);
        assert_eq!(stats.bar_count, 25_381);
        eprintln!(
            "[sub-window {} bars] {} naive -> {} sliding ({:.2}% redundancy)",
            stats.bar_count,
            fmt_ops(stats.total_naive_ops),
            fmt_ops(stats.total_sliding_ops),
            stats.redundancy_pct
        );
        for (name, naive, sliding, pct) in &stats.per_feature {
            eprintln!(
                "  {name:<10} {} naive -> {} sliding ({:.1}% redundancy)",
                fmt_ops(*naive),
                fmt_ops(*sliding),
                pct
            );
        }
        // The dominant features (SMA50, SMA200) are over 95% redundant
        // because their windows are large vs the per-bar slide cost.
        assert!(
            stats.redundancy_pct > 90.0,
            "expected >90% sub-window redundancy on 25k bars, got {:.1}%",
            stats.redundancy_pct
        );
        // SMA(200) specifically: 25,381 ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â 200 = 5.07M naÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¯ve, ~25k sliding.
        let sma200 = stats.per_feature.iter().find(|(n, _, _, _)| *n == "SMA(200)").expect("SMA(200) present");
        assert!(sma200.3 > 99.0, "SMA(200) should be >99% redundant, got {:.1}%", sma200.3);
    }

    #[test]
    fn legacy_store_migration_copies_trading_history() {
        let root = unique_test_dir("migrate-trading");
        let workspace = root.join("workspace");
        let primary = root.join("active-store");
        let legacy_history = workspace
            .join(".forge-store")
            .join("trading")
            .join("oanda")
            .join("NATGAS_USD");
        fs::create_dir_all(&legacy_history).expect("create legacy trading history");
        fs::write(
            legacy_history.join("H1.csv"),
            "time,open,high,low,close,volume\n2026-05-15T21:00:00.000000000Z,3.100,3.120,3.090,3.110,42\n",
        )
        .expect("write legacy H1 history");

        let previous_workspace_override = {
            let mut guard = workspace_override_lock().lock().expect("workspace override lock");
            let previous = guard.clone();
            *guard = Some(workspace.clone());
            previous
        };

        let migration_result = migrate_legacy_forge_store_data(&primary, None);

        {
            let mut guard = workspace_override_lock().lock().expect("workspace override lock");
            *guard = previous_workspace_override;
        }

        migration_result.expect("legacy migration succeeds");
        let migrated = primary
            .join("trading")
            .join("oanda")
            .join("NATGAS_USD")
            .join("H1.csv");
        assert!(migrated.exists(), "expected migrated trading history at {}", migrated.display());

        let _ = fs::remove_dir_all(&root);
    }

    #[test]
    fn atlas_peek_reports_brain_resolvable_pairs_on_cold_cache() {
        use scan::{MemoryGovernor, MonsterNode, Store};

        let path = std::env::temp_dir().join(format!(
            "forge-ui-test-atlas-peek-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&path);
        let store = Store::open(&path).expect("store open");
        let node = MonsterNode::new(store, MemoryGovernor::new(8 * 1024 * 1024));

        let examples: Vec<(i64, i64)> = (0..8).map(|i| (i, 1)).collect();
        let candidates = enumerate_synth_candidates_d2(&examples);
        let cse = cse_classify_candidates_with_reps(&candidates);
        let inputs: Vec<i64> = (0..16).collect();

        let (total, hits, pct) =
            synth_atlas_warm_estimate(&node, &cse.live_reps, &inputs, 64, 16);
        assert!(total > 0, "atlas peek total should be > 0");
        eprintln!(
            "[atlas peek] {hits}/{total} (program -> input) pairs brain-resolvable on cold cache ({pct:.1}%)"
        );
        // Most depth-2 affine programs (Add/Sub/Mul with a constant) are
        // resolved by the StructuralRule layer without the interpreter,
        // so we expect a healthy hit rate even on cold cache.
        assert!(
            pct > 5.0,
            "expected >5% brain-resolvable on cold cache, got {pct:.1}%"
        );

        let _ = std::fs::remove_dir_all(&path);
    }

    #[test]
    fn prestart_to_start_warm_path_avoids_raw_recompute() {
        let path = std::env::temp_dir().join(format!(
            "forge-ui-test-alpha-prestart-{}",
            std::process::id()
        ));
        let _ = std::fs::remove_dir_all(&path);

        let backend = ForgeBackend::new(path.clone()).expect("backend");
        let bars = sample_alpha_bars(trading::MIN_HISTORY + 96);
        let file_hash = 0xA17A_1234_u64;

        let (raw_feature_cache, cold_stats) = trading::build_raw_feature_cache_with_atlas(
            &bars,
            trading::MIN_HISTORY..bars.len(),
            &backend.atlas,
            file_hash,
        );
        assert!(
            cold_stats.computed_rows > 0,
            "cold build should compute some raw rows"
        );

        let persisted = persist_alpha_prestart_to_store(
            &backend,
            file_hash,
            &bars,
            &raw_feature_cache,
        )
        .expect("persist prestart");
        assert!(persisted, "first pre-start artifact should be new");

        let loaded = load_alpha_prestart_from_store(&backend, file_hash)
            .expect("load prestart result")
            .expect("prestart present");
        assert_eq!(loaded.manifest.raw_feature_rows_missing, 0);

        let start_plan = build_alpha_start_execution_plan(Some(&loaded), bars.len());
        assert!(start_plan.parsed_bars_from_prestart);
        assert_eq!(start_plan.raw_cache_source, "manifest-ready");
        assert!(!start_plan.refresh_prestart_after_raw_fill);

        let (_warm_cache, warm_stats) = trading::build_raw_feature_cache_with_atlas(
            loaded.bars.as_slice(),
            trading::MIN_HISTORY..loaded.bars.len(),
            &backend.atlas,
            file_hash,
        );
        assert_eq!(
            warm_stats.computed_rows, 0,
            "warm path should not recompute any raw row"
        );
        assert!(
            warm_stats.atlas_hits >= loaded.manifest.raw_feature_rows_ready,
            "warm path should rehydrate rows from atlas"
        );
        assert_eq!(avoided_pct(warm_stats.atlas_hits, warm_stats.computed_rows), 100.0);

        drop(backend);
        let _ = std::fs::remove_dir_all(&path);
    }

    #[test]
    fn avoided_pct_reports_full_avoidance_when_recompute_is_zero() {
        assert_eq!(avoided_pct(12, 0), 100.0);
        assert_eq!(avoided_pct(0, 0), 0.0);
        assert!((avoided_pct(9, 3) - 75.0).abs() < 1e-9);
    }

    #[test]
    fn native_cdp_parser_emits_accessible_nodes_with_bounds() {
        let dom = json!({
            "documents": [{
                "nodes": {
                    "parentIndex": [-1, 0],
                    "backendNodeId": [101, 102],
                    "nodeName": [0, 1],
                    "nodeValue": [0, 2],
                    "attributes": [
                        [],
                        [3, 4, 5, 6, 7, 8]
                    ]
                },
                "layout": {
                    "nodeIndex": [1],
                    "bounds": [[10.0, 20.0, 120.0, 40.0]],
                    "text": [2],
                    "styles": [[9, 10, 11, 11, 12, 13, 14, 15, 16]]
                }
            }],
            "strings": [
                "HTML",
                "A",
                "Click me",
                "href",
                "https://example.test/offers/1",
                "class",
                "cta-primary",
                "aria-label",
                "Contact agency",
                "block",
                "visible",
                "1",
                "rgba(0,0,0,0)",
                "none",
                "rgb(1,2,3)",
                "16px",
                "600"
            ]
        });
        let ax = json!({
            "nodes": [{
                "backendDOMNodeId": 102,
                "ignored": false,
                "role": { "value": "link" },
                "name": { "value": "Contact agency" },
                "value": { "value": "" },
                "properties": [
                    { "name": "disabled", "value": { "value": false } }
                ]
            }]
        });
        let nodes = webexplorer_native_collection_nodes_from_cdp(&dom, &ax);
        let link = nodes
            .iter()
            .find(|node| node.id == "native-backend-102")
            .expect("native link node");
        assert_eq!(link.aria_role, "link");
        assert_eq!(link.aria_name, "Contact agency");
        assert_eq!(link.href, "https://example.test/offers/1");
        assert!(link.bounds.is_some());
        assert_eq!(link.source, "native_cdp");
        assert!(link.ax.is_some());
    }

    #[test]
    fn native_cdp_parser_is_stable_for_identical_payloads() {
        let dom = json!({
            "documents": [{
                "nodes": {
                    "parentIndex": [-1, 0],
                    "backendNodeId": [201, 202],
                    "nodeName": [0, 1],
                    "nodeValue": [0, 2],
                    "attributes": [
                        [],
                        [3, 4]
                    ]
                },
                "layout": {
                    "nodeIndex": [1],
                    "bounds": [[1.0, 2.0, 300.0, 32.0]],
                    "text": [2],
                    "styles": [[5, 6, 7, 7, 8, 9, 10, 11, 12]]
                }
            }],
            "strings": [
                "HTML",
                "BUTTON",
                "Search",
                "role",
                "button",
                "inline-block",
                "visible",
                "1",
                "rgba(0,0,0,0)",
                "none",
                "rgb(40,40,40)",
                "14px",
                "500"
            ]
        });
        let ax = json!({
            "nodes": [{
                "backendDOMNodeId": 202,
                "ignored": false,
                "role": { "value": "button" },
                "name": { "value": "Search" },
                "value": { "value": "" },
                "properties": []
            }]
        });
        let first = webexplorer_native_collection_nodes_from_cdp(&dom, &ax);
        let second = webexplorer_native_collection_nodes_from_cdp(&dom, &ax);
        assert_eq!(first, second);
    }

    #[test]
    fn native_cdp_observe_v2_smoke_preserves_ax_fields_and_proof_hash_over_replay() {
        let dom = json!({
            "documents": [{
                "nodes": {
                    "parentIndex": [-1, 0, 1],
                    "backendNodeId": [301, 302, 303],
                    "nodeName": [0, 1, 2],
                    "nodeValue": [0, 0, 3],
                    "attributes": [
                        [],
                        [4, 5],
                        [6, 7, 8, 9]
                    ]
                },
                "layout": {
                    "nodeIndex": [1, 2],
                    "bounds": [
                        [0.0, 0.0, 1280.0, 80.0],
                        [24.0, 16.0, 240.0, 32.0]
                    ],
                    "text": [0, 3],
                    "styles": [
                        [10, 11, 12, 12, 13, 14, 15, 16, 17],
                        [18, 11, 12, 12, 13, 19, 20, 21, 22]
                    ]
                }
            }],
            "strings": [
                "HTML",
                "DIV",
                "A",
                "Explore listings",
                "class",
                "hero-shell",
                "href",
                "https://example.test/listings",
                "aria-label",
                "Explore listings",
                "block",
                "visible",
                "1",
                "rgba(0,0,0,0)",
                "none",
                "rgb(15,20,30)",
                "18px",
                "700",
                "inline-block",
                "rgb(0,87,184)",
                "16px",
                "600",
                "underline"
            ]
        });
        let ax = json!({
            "nodes": [{
                "backendDOMNodeId": 303,
                "ignored": false,
                "role": { "value": "link" },
                "name": { "value": "Explore listings" },
                "value": { "value": "" },
                "properties": [
                    { "name": "focusable", "value": { "value": true } }
                ]
            }]
        });
        let native_nodes = webexplorer_native_collection_nodes_from_cdp(&dom, &ax);
        assert!(
            native_nodes.iter().any(|node| node.ax.is_some()),
            "native CDP nodes should carry AX evidence"
        );
        assert!(
            native_nodes
                .iter()
                .any(|node| !node.aria_name.trim().is_empty() && !node.aria_role.trim().is_empty()),
            "native CDP nodes should expose non-empty AX role/name fields"
        );

        let first = collection_os::finalize_collection_observe_v2(collection_os::CollectionObserveInputV2 {
            source_url: "https://example.test/listings".to_string(),
            title: "Native CDP smoke".to_string(),
            tree_hash: "native-tree-301".to_string(),
            captured_at_ms: 1_717_171_717,
            viewport: Some(collection_os::CollectionObserveViewport {
                width: 1280.0,
                height: 720.0,
                scroll_x: 0.0,
                scroll_y: 0.0,
            }),
            nodes: native_nodes.clone(),
            scene_blocks: Vec::new(),
            proof_hash: String::new(),
        });
        let second = collection_os::finalize_collection_observe_v2(collection_os::CollectionObserveInputV2 {
            source_url: "https://example.test/listings".to_string(),
            title: "Native CDP smoke".to_string(),
            tree_hash: "native-tree-301".to_string(),
            captured_at_ms: 1_717_171_717,
            viewport: Some(collection_os::CollectionObserveViewport {
                width: 1280.0,
                height: 720.0,
                scroll_x: 0.0,
                scroll_y: 0.0,
            }),
            nodes: native_nodes,
            scene_blocks: Vec::new(),
            proof_hash: String::new(),
        });

        assert!(first.proof_hash.starts_with("kasm://sha256/"));
        assert_eq!(first.proof_hash, second.proof_hash);
        assert!(
            first.nodes.iter().any(|node| {
                node.ax
                    .as_ref()
                    .is_some_and(|ax| ax.role == "link" && ax.name == "Explore listings")
            }),
            "observe_v2 replay should preserve native AX semantics"
        );
    }
